window.JBLNUM_SEED=window.JBLNUM_SEED||{};JBLNUM_SEED["OMED"]={"meta":{"id":"OMED","t":"임상구강내과학","short":"구강내과","src":"임상구강내과학 넘버링 (채연, 진서)_26updateby쭘","file":"임상구강내과학 넘버링 Word (26 update)","legend":{"#FFFF00":"기출","#00FF00":"수업시간 강조","#00FFFF":"과거기출"},"layout":"qas","n":72},"lecs":[{"k":"L14ef69","t":"내분비, 임신","raw":"고홍섭_내분비, 임신","lab":"","prof":"고홍섭","date":""},{"k":"L48f703","t":"근신경계 질환","raw":"0519 정진우_근신경계 질환","lab":"","prof":"정진우","date":"0519"},{"k":"Ld212a1","t":"당뇨","raw":"0526 고홍섭_당뇨","lab":"","prof":"고홍섭","date":"0526"},{"k":"L95cf01","t":"감염성질환, 성병, AIDS","raw":"0609 박희경_감염성질환, 성병, AIDS","lab":"","prof":"박희경","date":"0609"},{"k":"L99f76c","t":"암, 이식환자, 알러지","raw":"0616 박지운_암, 이식환자, 알러지","lab":"","prof":"박지운","date":"0616"},{"k":"L1626ef","t":"정신질환","raw":"0617 박지운_정신질환","lab":"","prof":"박지운","date":"0617"}],"items":[{"id":"sd:OMED:cfbeb91f","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\"><b>Cortisol-anti-inflammatory action (25탈)<\/b><\/span><\/p><p><br><\/p><p><b>25년도: Corticosteroid의 <\/b><\/p><p><b>면역억제 기전을 설명하시오.<\/b><\/p>","a":"<p>Inhibit<\/p><p>1. lysosome release<\/p><p>2. prostaglandin production<\/p><p>3. leukocyte function<\/p><p>4. cytokine release<\/p><p>5. endothelial cell expression of adhesion molecules (ICAM, ECAM)<\/p><p><img data-nimg=\"d10c6789.webp\" width=\"193\" height=\"132\" alt=\"\"> <\/p><p><span style=\"color:#7F7F7F;\">*steroidal : <\/span><\/p><p><span style=\"color:#7F7F7F;\">phospholipase A2 억제 → prostaglandin production 억제, 염증억제<\/span><\/p><p><br><\/p><p><span style=\"color:#7F7F7F;\">*non-steroidal(ex. NSAIDs) : <\/span><\/p><p><span style=\"color:#7F7F7F;\">cyclooxygenase 억제 → prostaglandin 억제<\/span><\/p>","st":"<p><span style=\"color:#C00000;\">Cor꼴!! <\/span><\/p><p><span style=\"color:#C00000;\">Pro 들이 cytokine 싸커킥<\/span><\/p><p><span style=\"color:#C00000;\">Leu 룰루 lys랄라<\/span><\/p><p><span style=\"color:#C00000;\">END CAM에 담겼어<\/span><\/p>","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T0r2"},{"id":"sd:OMED:8c4ddbf6","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\"><b>ACTH 풀네임 (24)<\/b><\/span><\/p>","a":"<p>Adrenocorticotropic Hormone<\/p>","st":"","yrs":[2024],"tags":["기출"],"lab":"","pos":"T0r3"},{"id":"sd:OMED:b0fff5e7","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\"><b>Cortisol 결핍인 <\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>1차성 질환은? (24)<\/b><\/span><\/p><p><b>(1) cortisol 결핍인 1차성 질환은?<\/b><\/p><p><b>(2) 뇌하수체에서 부신 자극하면서 (  )가 나오고 (   )가 같이 나온다.<\/b><\/p><p>(모두 영어 풀네임으로!!) <\/p>","a":"<p><span style=\"color:#C00000;\">(1) Addison disease<\/span><\/p><p><span style=\"color:#C00000;\">(2) Adrenocorticotropic hormone<\/span><\/p>","st":"","yrs":[2024],"tags":["기출"],"lab":"","pos":"T0r4","rv":[{"k":"fix","m":"Word에서 '정답' 칸에 문제((1)(2)), '암기법' 칸에 답이 있어 칸만 옮김 — 문제 = 문제+정답 칸 글, 답 = 암기법 칸 글(글자 그대로), 스토리 비움"}]},{"id":"sd:OMED:e907a937","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\"><b>Hypoadrenalism, Adrenal insufficiency<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>객관식<\/b><\/span><\/p>","a":"<p><span style=\"color:#7F7F7F;\">*HPA axis : hypothalamic (CRH) – pituitary (ACTH) – adrenal (cortisol)- axis<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HPT axis : hypothalamic (TRH) – pituitary (TSH) – thyroid (T3, T4) – axis<\/span><\/p><p>1. Primary<\/p><p><img data-nimg=\"bf56d53f.webp\" width=\"240\" height=\"123\" alt=\"\">(1) Progressive destruction of <u>adrenal glands<\/u><\/p><p>   ➢ idiopathic (autoimmune)<\/p><p>   ➢ malignancy<\/p><p>   ➢ infection (Tb, HIV)<\/p><p>      - weakness, anorexia, dehydration, weight loss<\/p><p>      - hypotension<\/p><p>      - <b>abnormal pigmentation<\/b> of skin, mucosa<\/p><p>(2) Problems related with <u>cortisol, aldosterone<\/u><\/p><p>(3) <u>Addison’s disease<\/u><\/p><p><span style=\"color:#7F7F7F;\">*adrenal gland 자체의 문제 → steroid, mineralocorticoid 생성 어려워짐<\/span><\/p><p><span style=\"color:#7F7F7F;\">*primary의 경우에만 점막 pigmentation 생김 (Pituitary gland에서 ACTH, MSH 과다분비)<\/span><\/p><p>2. Secondary<\/p><p>(1) structural lesions of <u>pituitary gland<\/u><\/p><p>(2) removal of <u>pituitary gland<\/u><\/p><p>(3) <u>Lack of responsiveness of the adrenal glands<\/u> to ACTH<\/p><p>(4) Critical illness (liver cirrhosis, sepsis)<\/p><p><span style=\"color:#7F7F7F;\">*다른 이유로 adrenal gland가 영향 받음 → pituitary gland 문제나 이로인해 adrenal gland 기능이상이 생긴 경우<\/span><\/p><p><br><\/p><p>3. Tertiary<\/p><p>(1) Defective function of <u>hypothalamus<\/u><\/p><p>(2) Chronic corticosteroid administration<\/p><p>(3) Problems related with <u>cortisol<\/u><\/p><p><span style=\"color:#7F7F7F;\">*hypothalamus 문제, 외부에서 gcc를 약제로 너무 많이 주는 경우 → mineralcorticoid에 영향 X<\/span><\/p><p> <\/p><p><span style=\"background-color:#FFFF00;\">*Adrenal insufficiency 설명으로 옳은 것은?<\/span><\/p><p>1) 1차 시상하부 2차 뇌하수체<\/p><p>2) 1차 cortisol 2차 cortisol aldosterone<\/p><p>3) 1,2차에서 모두 pigmentation 일어난다<\/p><p>4) 이 환자는 감염에 매우 취약하다는 것을 유념<\/p><p>5) Addison disease는 1,2차에 모두 해당하는 질병                                 (<b>정답 : 4번)<\/b><\/p>","st":"<p><span style=\"color:#C00000;\">꼴 = goal<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Prime 선수)<\/span><\/p><p><span style=\"color:#C00000;\">아드레날린 분비<\/span><\/p><p><span style=\"color:#C00000;\">꼴 넣고 안도했음<\/span><\/p><p><span style=\"color:#C00000;\">기록 add함<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Second 선수)<\/span><\/p><p><span style=\"color:#C00000;\">Pit에서 자리만 채우고<\/span><\/p><p><span style=\"color:#C00000;\">결국 pit에서 제거됨<\/span><\/p><p><span style=\"color:#C00000;\">아드레날린 없이 책임감이 없대나<\/span><\/p><p><span style=\"color:#C00000;\">암 크리티컬하지<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Third 선수)<\/span><\/p><p><span style=\"color:#C00000;\">너 어디 hypo? 아퍼? <\/span><\/p><p><span style=\"color:#C00000;\">만성적으로 꼴을 못 넣어서<\/span><\/p><p><span style=\"color:#C00000;\">꼴 결정력 문제 생김<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T0r5"},{"id":"sd:OMED:80195bd3","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\"><b>25 빈칸빵<\/b><\/span><\/p><p><b>In dental practice, clinician should consider adverse interaction with (1) and other pressor amines in patient with hyperthyroidism and exacerbate response to (2) in patient with hypothyroidism. <\/b><\/p>","a":"<p><span style=\"color:#C00000;\">(1) epinephrine<\/span><br><span style=\"color:#C00000;\">(2) CNS depressants<\/span><\/p>","st":"","yrs":[2025],"tags":["기출"],"lab":"","pos":"T0r6","rv":[{"k":"year","m":"줄머리 '25 빈칸빵'를 2025년 출제로 읽음"},{"k":"fix","m":"Word에서 '정답' 칸에 빈칸 문제((1)(2)), '암기법' 칸에 답이 있어 칸만 옮김 — 문제 = '25 빈칸빵' + 빈칸 문장, 답 = (1)(2) 답(글자 그대로), 스토리 비움"}]},{"id":"sd:OMED:e3af41a9","lec":"L14ef69","q":"<p><span style=\"background-color:#00FFFF;\"><b>Adrenal insufficiency 치과치료 시 주의사항<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25, 과거객)<\/b><\/span><\/p><p><br><\/p><p><b>25년도: 주의사항만 물어봄<\/b><\/p>","a":"<p><b>[Potential problems related to dental care]<\/b><\/p><p>1. inability to tolerate stress<\/p><p>2. delayed healing (secondary/tertiary)<\/p><p>3. susceptibility to infection (secondary/tertiary)<\/p><p><b>[Oral complication]<\/b><\/p><p>1. pigmentation (primary)<\/p><p>- The melanocyte stimulating hormone (MSH) is co-secreted along with ACTH.<\/p>","st":"<p><span style=\"color:#C00000;\">골 못 넣었을 때의 문제)<\/span><\/p><p><span style=\"color:#C00000;\">스트레스 받아!!<\/span><\/p><p><span style=\"color:#C00000;\">힐링하려면 결국 success해야해<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">결국 입으로 많이 먹어서 돼지됨<\/span><\/p>","yrs":[2025],"tags":["과거기출","기출"],"lab":"","pos":"T0r7"},{"id":"sd:OMED:d8a17510","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\">Adrenal insufficiency 의심 환자에게 Steroid supplement 치료할 때 주의사항<\/span><\/p>","a":"<p><b>[Considerations]<\/b><\/p><p>1) Severity of surgery<\/p><p>2) Level of pain control<\/p><p>3) Amount of cortisol produced during the physiologic response to surgical stress<\/p><p>4) Overall health of patient<\/p><p><b>[Steroid supplementation]<\/b><\/p><p><img data-nimg=\"fd1fb4bd.webp\" width=\"384\" height=\"71\" alt=\"\"><\/p><p><span style=\"color:#7F7F7F;\">*steroid supplementation = 이미 스테로이드 복용중/복용했던 사람에게 추가로 더 주는 것<\/span><\/p><p><span style=\"color:#7F7F7F;\">*steroid 치료 받고 있는 치과 방문 환자들 : adrenal gland atrophy가 있을 가능성 높음. 환자에게 stress 주는 치과치료에서 코티솔 제대로 만들지 못해 stress 취약 → steroid supplementation 필요할 수 있음<\/span><\/p><p><span style=\"color:#7F7F7F;\">*routine = 일반적인 진료, extensive = 4개 이상의 발치/수술 등<\/span><\/p><p><br><\/p><p><b>[steroid supplementation - dose]<\/b><\/p><p>1) minor surgical stress<\/p><p>- 25mg of hydrocortisone equivalent (6mg prednisone) on the day of surgery<\/p><p>2) moderate surgical stress<\/p><p>- 50~75mg per day of hydrocortisone equivalent for up to 1~2 days<\/p><p>3) major surgical stress<\/p><p>-100~150mg per day of hydrocortisone equivalent for up to 2~3 days<\/p><p> Only patients with primary adrenal insufficiency receive <u>supplemental doses of steroid<\/u>, whereas those with secondary adrenal insufficiency who take daily corticosteroids, regardless of the type of surgery, should receive only their <u>usual daily dose of corticosteroid before the surgery<\/u>.<\/p>","st":"<p><span style=\"color:#C00000;\">꼴 못 넣어서 치료 받음)<\/span><\/p><p><span style=\"color:#C00000;\">수술하자..<\/span><\/p><p><span style=\"color:#C00000;\">레벨 넘으려면 고통도 견뎌야지<\/span><\/p><p><span style=\"color:#C00000;\">수술 후 피지컬 좋아져서 꼴 잘 넣고<\/span><\/p><p><span style=\"color:#C00000;\">건강 좋아짐<\/span><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Adrenal insufficiency로 환자 아파서 cortisol 투여 수술 받음.<\/span><\/p><p><span style=\"color:#C00000;\">Primary – supplemental dose of steroid<\/span><\/p><p><span style=\"color:#C00000;\">Secondary – usual daily dose of corticosteroid<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T0r8"},{"id":"sd:OMED:346f961b","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\">Hyperthyroidism, Hypothyroidism의 <\/span><\/p><p><span style=\"background-color:#FFFF00;\">전신증상<\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p><br><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><span style=\"background-color:#FFFF00;\"><b>Hyperthyroidism<\/b><\/span><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Hypothyroidism<\/b><\/p><\/td><\/tr><tr><td><p><b>Skeletal<\/b><\/p><\/td><td><p>osteoporosis<\/p><\/td><td><p>Arthritis, cramps<\/p><\/td><\/tr><tr><td><p><b>C-V<\/b><\/p><\/td><td><p>Arrhythmias, CHF<\/p><\/td><td><p>Slow pulse, hypertension<\/p><\/td><\/tr><tr><td><p><b>G-I<\/b><\/p><\/td><td><p>Weight loss, appetite ↑<\/p><\/td><td><p>Weight gain, Constipation<\/p><\/td><\/tr><tr><td><p><b>CNS<\/b><\/p><\/td><td><p>Lability, tremors<\/p><\/td><td><p>Slowness, sleepiness<\/p><\/td><\/tr><tr><td><p><b>Skin<\/b><\/p><\/td><td><p>Erythema<\/p><\/td><td><p>Dry<\/p><\/td><\/tr><tr><td><p><b>eye<\/b><\/p><\/td><td><p>exophthalmos<\/p><\/td><td><p>blurred<\/p><\/td><\/tr><\/table><p><span style=\"color:#7F7F7F;\">*C-V : cardiovascular / CHF : congestive heart failure / G-I : gastrointestinal / cramp : 근육경련 / arrhythmias : 부정맥<\/span><\/p><p><span style=\"color:#7F7F7F;\">*exophthalmos : mucopolysaccharide infiltration 때문에 눈 튀어나와 잠잘 때 눈 감지 못할 정도로 심함<\/span><\/p><p><span style=\"color:#7F7F7F;\">*hypothyroidism에 의해 geographic tongue, macroglossia 보임<\/span><\/p>","st":"<p><span style=\"color:#C00000;\">O po.. 오빠  / A cr 아크!!<\/span><\/p><p><span style=\"color:#C00000;\">아니이이(아리) CH 채널 돌리다가 /<\/span><\/p><p><span style=\"color:#C00000;\">넌 hype 되었는데 나는 sl pu 슬퍼<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">넌 몸무게 줄고 식욕 늘었는데 / 난 살찌고 변비야<\/span><\/p><p><span style=\"color:#C00000;\">넌 트랙 tre la 뛰고 / 난 느리고 졸리기만 해<\/span><\/p><p><span style=\"color:#C00000;\">에라이 ery / dry 다 죽어버려<\/span><\/p><p><span style=\"color:#C00000;\">알았어 Exo / 보자 <\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T0r9"},{"id":"sd:OMED:a0786f0c","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\"><b>Hyperthyroidism, Hypothyroidism의 Oral complications<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25탈)<\/b><\/span><\/p><p><br><\/p><p><b>25년도: hypothyroidism만 물어봄<\/b><\/p>","a":"<p><b>[Hyperthyroidism]<\/b><\/p><p>1) Osteoporosis<\/p><p>2) Premature loss of primary teeth and early eruption of permanent teeth : Dental caries, periodontal ds.<\/p><p>3) Early jaw development<\/p><p>4) Xerostomia after radioactive iodine tx.<\/p><p><br><\/p><p><b>[Hypothyroidism]<\/b><\/p><p>1) Increase in tongue size<\/p><p>2) Delayed eruption of teeth<\/p><p>3) Malocclusion<\/p><p>4) Gingival edema<\/p><p>5) burning mouth syndrome<\/p><p>6) Oral lichen planus<\/p>","st":"<p><span style=\"color:#C00000;\">오빠!!<\/span><\/p><p><span style=\"color:#C00000;\">아마추어는 못 오는 얼리 매장에서<\/span><\/p><p><span style=\"color:#C00000;\">얼리 제품 사줄테니까<\/span><\/p><p><span style=\"color:#C00000;\">X 잊고 나랑 active하게 놀쟈<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Tongue 키스하면서<\/span><\/p><p><span style=\"color:#C00000;\">치아도 만짐<\/span><\/p><p><span style=\"color:#C00000;\">말 하지마<\/span><\/p><p><span style=\"color:#C00000;\">진짜<\/span><\/p><p><span style=\"color:#C00000;\">뜨겁게<\/span><\/p><p><span style=\"color:#C00000;\">Lichen 리쳐보쟈 or Lp바에서 놀아보쟈<\/span><\/p>","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T0r10"},{"id":"sd:OMED:1299ddb8","lec":"L14ef69","q":"<p><span style=\"background-color:#00FFFF;\">Hyperthyroidism, Hypothyroidism의 치과치료 시 문제점<\/span><\/p><p><br><\/p><p><span style=\"background-color:#00FFFF;\">Potential problems related to dental care<\/span><\/p>","a":"<p><b>[Hyperthyroidism]<\/b><\/p><p>1. Thyrotoxic crisis (Thyroid storm)<\/p><p>-infection (acute) / trauma / surgical procedures / stress<\/p><p>2 adverse interaction with Epinephrine and other pressor amine<\/p><p>3 cardiac problems<\/p><p>- arrhythmia(부정맥) / congestive heart failure<\/p><p><br><\/p><p><b>[Hypothyroidism]<\/b><\/p><p>1. hypothyroid (myxedematous) coma<\/p><p>-infection (acute) / surgical procedures / CNS depressants<\/p><p>2. exaggerated response to CNS depressants in uncontrolled hypothyroidism<\/p><p> <\/p><p><span style=\"background-color:#FFFF00;\">(객관식) 각각에 대해 hypothyroidism의 증상을 고르세요 (22)<\/span><\/p><p>(임상증상)   -weight loss / blurred vision / hypertension / tremor<\/p><p>(구강증상)  -early jaw development / increase in tongue size / jaw osteoporosis / oral lichen planus<\/p><p><b>(정답)<\/b><\/p><p>- weight gain / blurred vision / hypertension<\/p><p>- increase in tongue size / oral lichen planus<\/p>","st":"<p><span style=\"color:#C00000;\">타로점 보다가 헤어짐<\/span><\/p><p><span style=\"color:#C00000;\">INFp여서 트라우마 스트레스 수술받음<\/span><\/p><p><span style=\"color:#C00000;\">부작용으로 전여친 에피소드 넘치는<\/span><\/p><p><span style=\"color:#C00000;\">Car을 못 탐ㅠ<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">결국 hypo하다가 코마 옴<\/span><\/p><p><span style=\"color:#C00000;\">CSI와서 부검하는데<\/span><\/p><p><span style=\"color:#C00000;\">우울증 약에 대한 과장 반응으로 uncontrolled 된거래ㅠ<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T0r11"},{"id":"sd:OMED:d4e79b61","lec":"L14ef69","q":"<p><span style=\"background-color:#00FFFF;\">임신 시 dental care problem<\/span><\/p>","a":"<p><span style=\"background-color:#00FFFF;\">Potential problems related to dental care<\/span><\/p><p>1. potential harm to fetus<\/p><p>2. supine hypotension in late pregnancy<\/p><p>3. poor nutrition<\/p><p>4. transmission of drug to infants via breast milk<\/p>","st":"<p><span style=\"color:#C00000;\">임신 하면<\/span><\/p><p><span style=\"color:#C00000;\">누(nu)구라도 해(harm)로운<\/span><\/p><p><span style=\"color:#C00000;\">약(drug)은 피함<\/span><\/p><p><span style=\"color:#C00000;\">Sup 수퍼맨이 되려면 hypo아픈 법<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T0r12"},{"id":"sd:OMED:0d554277","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\">FDA Categorization<\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25, 25수업강조)<\/b><\/span><\/p><p><br><\/p><p><b>25년도: glucocorticoids의 임신 중 FDA category 및 그 의미를 쓰시오.<\/b><\/p><p><br><\/p><p>(답: C, no human study, risk to fetus)<b> <\/b><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p><br><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Human study<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Animal study<\/b><\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\"><b>A<\/b><\/p><\/td><td colspan=\"2\"><p>No risk to fetus in human (proven safe)<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\"><b>B<\/b><\/p><\/td><td><p>No human study<\/p><\/td><td><p>No risk to fetus<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\"><b>B<\/b><\/p><\/td><td><p>No risk to fetus<\/p><\/td><td><p>Risk to fetus<\/p><\/td><\/tr><tr><td rowspan=\"2\"><p style=\"text-align:center;\"><b>C<\/b><\/p><\/td><td><p>No human study<\/p><\/td><td><p>Risk to fetus<\/p><\/td><\/tr><tr><td colspan=\"2\"><p>No available human or animal studies<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\"><b>D<\/b><\/p><\/td><td colspan=\"2\"><p>Risk to fetus in human (may be used)<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\"><b>X<\/b><\/p><\/td><td colspan=\"2\"><p>Risk to fetus in human (Risk &gt; Benefit)<\/p><\/td><\/tr><\/table><p><br><\/p><p><span style=\"background-color:#FFFF00;\">*임신 중 복용약물에 대한 FDA 분류 B의 의미를 쓰시오<\/span><\/p><p>-No human study and No risk to fetus in animal study<\/p><p>-No risk to fetus in human study and Risk to fetus in animal study<\/p>","st":"","yrs":[2025],"tags":["기출","25 수업 강조"],"lab":"","pos":"T0r13"},{"id":"sd:OMED:3ea564fb","lec":"L14ef69","q":"<p><span style=\"background-color:#FFFF00;\">Pregnancy and Lactation<\/span><\/p><p><span style=\"background-color:#FFFF00;\">다음 중 수유 안 되는 것은?<\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Drug<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>FDA<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Pregnancy<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Lactation<\/b><\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Lidocaine<\/p><\/td><td><p style=\"text-align:center;\">B<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Ibuprofen<\/p><\/td><td><p style=\"text-align:center;\">C/D3<\/p><\/td><td><p style=\"text-align:center;\">Avoid in 3rd trimester<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Aspirin<\/p><\/td><td><p style=\"text-align:center;\">C/D3<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Acetaminophen<\/p><\/td><td><p style=\"text-align:center;\">B<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Penicillin<\/p><\/td><td><p style=\"text-align:center;\">B<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Erythromycin<\/p><\/td><td><p style=\"text-align:center;\">B<\/p><\/td><td><p style=\"text-align:center;\">O (Avoid estolate form)<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Cephalosporin<\/p><\/td><td><p style=\"text-align:center;\">B<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Tetracycline<\/p><\/td><td><p style=\"text-align:center;\">D<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Glucocorticoids<\/p><\/td><td><p style=\"text-align:center;\">C<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Benzodiazepine<\/p><\/td><td><p style=\"text-align:center;\">D/X<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><td><p style=\"text-align:center;\">Avoid<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">Nitrous oxide<\/p><\/td><td><p><br><\/p><\/td><td><p style=\"text-align:center;\">Best use in 2nd&amp;3rd trimester, &lt;30 min<\/p><\/td><td><p style=\"text-align:center;\">O<\/p><\/td><\/tr><\/table><p><span style=\"color:#7F7F7F;\">*Lactation 금지 : aspirin, tetracycline, benzodiazepine<\/span><\/p><p><span style=\"color:#7F7F7F;\">*Pregnancy 금지 : ibuprofen, aspirin, erythromycin, tetracycline, glucocorticoids, benzodiazepine<\/span><\/p><p><span style=\"color:#7F7F7F;\">*FDA : 대체로 B<\/span>        <\/p><p><span style=\"color:#7F7F7F;\">*D3 = 3rd trimester에서는 D단계 약물로 작용한다는 의미 → 이 시기에는 사용 불가<\/span><\/p><p> <\/p><p><span style=\"background-color:#FFFF00;\"><b>*FDA B에 해당하지 않는 약을 모두 고르시오<\/b><\/span><\/p><p>Acetaminophen, cephalosporin, penicillin, lidocaine, benzodiazepine, glucocorticoid, tetracyline<\/p><p><b>정답 : Benzodiazepine, glucocorticoid, tetracycline<\/b><\/p>","st":"<p><span style=\"color:#C00000;\">*Lactation 금지<\/span><\/p><p><span style=\"color:#C00000;\">티트리(tetra) 금지(ben) ! 아씨(as),,,<\/span><\/p><p><span style=\"color:#C00000;\"> <\/span><\/p><p><span style=\"color:#C00000;\">*Pregnancy 금지<\/span><\/p><p><span style=\"color:#C00000;\">이부(ibu)지리가 이리(ery)도 넓으니(tera) glu글로가도 절로가도 떨어지기 금지(ben) AS도 가능함~<\/span><\/p><p><span style=\"color:#C00000;\"> <\/span><\/p><p><span style=\"color:#C00000;\">(1) C/D3 : ibuprofen, aspirin<\/span><\/p><p><span style=\"color:#C00000;\">이불(ibu) 위에서 에스파(asp) CD 노래 들음<\/span><\/p><p><span style=\"color:#C00000;\">(2) D : tetracycline<\/span><\/p><p><span style=\"color:#C00000;\">울트라(tra) D 라인<\/span><\/p><p><span style=\"color:#C00000;\">(3) C : glucocorticoids<\/span><\/p><p><span style=\"color:#C00000;\">corticoids → C<\/span><\/p><p><span style=\"color:#C00000;\">(4) Benzodiazepine : D/X<\/span><\/p><p><span style=\"color:#C00000;\">ben금한다 XXX<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T0r14"},{"id":"sd:OMED:b67658f1","lec":"L14ef69","q":"<p><span style=\"background-color:#00FFFF;\"><b>Corticosteroid 경구투여 시 아침 9시 이전 복용하는 이유는?<\/b><\/span><\/p>","a":"<p>- 일반적인 사람에서 cortisol은 오전 2시~8시 사이에 분비되는 <u>circadian rhythm<\/u>을 보인다.<\/p><p>- 경구투여 시 corticosteroid는 adrenal gland atrophy를 방지하기 위해서 (minimal endogenous corticosteroid suppression을 위해) 9시 이전에 복용한다.<\/p><p> <\/p><p><b>[PPT 답안]<\/b><\/p><p>(1) Normal cortisol release occurs<\/p><p>- around 2-8 am<\/p><p>- late afternoon and early evening in individuals working the night shift<\/p><p>(2) Exogenous corticosteroids will cause minimal endogenous corticosteroid suppression when the exogenous dose is given prior to 9 am.<\/p><p><img data-nimg=\"5dbd5767.webp\" width=\"278\" height=\"111\" alt=\"\"><\/p>","st":"","yrs":[],"tags":["과거기출"],"lab":"","pos":"T0r15"},{"id":"sd:OMED:0b1abf16","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>Epilepsy의 원인 (24,22)<\/b><\/span><\/p>","a":"<p>1. Idiopathic or primary epilepsy<\/p><p>2. Head trauma<\/p><p>3. Developmental abnormalities<\/p><p>4. Intracranial neoplasm<\/p><p>5. Hypoglycemia<\/p><p>6. Cerebrovascular disease<\/p><p>7. Drug withdrawal<\/p><p>8. Febrile illness (meningitis, encephalitis)<\/p><p>9. Genetic disease - down syn, tuberous sclerosis, neurofibromatosis<\/p>","st":"<p><span style=\"color:#C00000;\">예쁜 아이디어 없어?<\/span><\/p><p><span style=\"color:#C00000;\">머리가 발달을 안해서 없어..<\/span><\/p><p><span style=\"color:#C00000;\">네오트로 먹으면 당 떨어져서<\/span><\/p><p><span style=\"color:#C00000;\">학점 C, D, F 나올듯..<\/span><\/p><p><span style=\"color:#C00000;\">걍 유전자 문제야 DTN 다시 태어나쟈<\/span><\/p>","yrs":[2024,2022],"tags":["기출"],"lab":"","pos":"T1r2"},{"id":"sd:OMED:f8e46a55","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>긴장성-강대성 발작의 임상소견을 기술하시오. (24,23)<\/b><\/span><\/p><p><b>= <\/b><b><u>Grand mal seizure<\/u><\/b><b> 의 증상<\/b><\/p>","a":"<p>1. Aura: unusual smell of visual disturbance(30% of pts.)<\/p><p>2. Irritability: another premonitory signal<\/p><p>3. Epileptic cry: caused by spasm of diaphragmatic m.<\/p><p>4. Immediately loose consciousness<\/p><p>5. Tonic phase<\/p><p>- generalized m. rigidity, pupil dilatation, eyes rolling upward or to the side,<\/p><p>- loss of consciousness<\/p><p>6. Clonic phase<\/p><p>- uncoordinated beating movement of limbs and head<\/p><p>- forcible jaw closing, head rocking<\/p><p>7. After a few mins: movement cease, m. relax, and gradual return to consciousness<\/p><p>8. Stupor, headache, confusion and depression<\/p>","st":"<p><span style=\"color:#C00000;\">(긴장한 채 거울보는 중)<\/span><\/p><p><span style=\"color:#C00000;\">A: 어라..이 냄새와 비주얼?<\/span><\/p><p><span style=\"color:#C00000;\">이리도 예쁜 사람이 있네?<\/span><\/p><p><span style=\"color:#C00000;\">B: 정신 나갔네.. 토나온다 눈 삐었어?<\/span><\/p><p><span style=\"color:#C00000;\">A: 클났당~ 심장 beat 턱이 안다물어져<\/span><\/p><p><span style=\"color:#C00000;\">B: 릴랙스해봐.. 돌아와야지 이제<\/span><\/p><p><span style=\"color:#C00000;\">A: 쉿(SH) 혼란스러워<\/span><\/p>","yrs":[2024,2023],"tags":["기출"],"lab":"","pos":"T1r3"},{"id":"sd:OMED:397fc450","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>뇌졸중의 원인 모두 쓰시오. <\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25탈?)<\/b><\/span><\/p>","a":"<p>1) Thrombosis of cerebral vessel (60-80%)<\/p><p>2) Cerebral embolism<\/p><p>3) Intracranial hemorrhage<\/p><p>4) Primary factors associated stroke-cerebrovascular disease<\/p><p>- Atherosclerosis<\/p><p>- hypertensive vascular disease<\/p><p>- cardiac pathosis (myocardial infarction, atrial fibrillation)<\/p><p>5) additional factors associated stroke<\/p><p>- transient ischemic attack<\/p><p>- previous stroke<\/p><p>- high dietary fat<\/p><p>- obesity<\/p><p>- elevated blood lipid levels<\/p><p>- physical inactivity<\/p><p>- uncontrolled hypertension<\/p><p>- cardiac abnormalities<\/p><p>- diabetes mellitus<\/p><p>- elevated homocysteine levels<\/p><p>- elevated hematocrit<\/p><p>- elevated antiphospholipid antibodies<\/p><p>- heavy tobacco smoking<\/p><p>- increasing age<\/p><p>- periodontal disease<\/p>","st":"","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T1r4","rv":[{"k":"year","m":"연도 뒤 물음표 (25탈?)"}]},{"id":"sd:OMED:cc7a4a08","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>간질 환자의 치과치료 시 주의사항에 대해 서술하시오. (25,23)<\/b><\/span><\/p>","a":"<p>1. Identification of patient by history<\/p><p>- Type of seizure<\/p><p>- Age at time of onset<\/p><p>- Cause of seizures (if known)<\/p><p>- Medications<\/p><p>- Frequency of physician visits (name and phone number)<\/p><p>- Degree of seizure control<\/p><p>- Frequency of seizures<\/p><p>- Date of last seizure<\/p><p>- Known precipitating factors<\/p><p>- History of Seizure-related injuries<\/p><p>2. Well controlled seizures: provide normal care<\/p><p>3. Questionable history or poorly controlled seizures: consultation with physician before dental treatment<\/p><p>4. Be alert to adverse effects of anticonvulsants<\/p><p>- Drowsiness<\/p><p>- Slow mentation<\/p><p>- Dizziness<\/p><p>- Ataxia<\/p><p>- Gastrointestinal upset<\/p><p>- Allergic signs<\/p><p>5. Valproic acid (Depakene)  or carbamazepine (Tegretol)  복용 환자: 비정상이라면 내과의와 상담<\/p><p>6. Be prepared to manage grand mal seizure<\/p><p>- Ligated mouth prop 사용<\/p><p>- Supine position<\/p><p>7. Manage the seizure<\/p><p>- Clear area<\/p><p>- Turn patient to side (to avoid aspiration)<\/p><p>- Do not attempt to use padded tongue blade<\/p><p>- Passively restrain<\/p><p>8. Medication        - Prodromal sign: 0.5~2mg Iorazepam(설하), 2-10mg diazepam (IV)<\/p><p>- Prolonged seizure: 4-8mg Iorazepam(설하), 10mg diazepam<\/p><p>9. After the seizure            - Traumatic injury 확인<\/p><p>- 치료 중단, 환자 이송 준비<\/p><p><br><\/p><p><b>[정리본 더 줄인 ver.]<\/b><\/p><p>1. 환자의 hx. 파악<\/p><p>2. 간질 control이 잘되는 환자는 normal care 가능<\/p><p>3. hx.가 불분명한 경우 혹은 control이 잘 안되는 간질 환자의 경우 내과의와 상의<\/p><p>4. anticonvulsant의 부작용에 대해 파악해두기 (drowsiness, slow mentation, dizziness)<\/p><p>5. valproic acid나 carbamazepine 복용하는 경우 bleeding time에 대해 내과의와 상의<\/p><p>6. grand mal seizure에 대비<\/p><p>7. seizure 일으키는 경우 환자 주위를 치우고, 환자를 옆으로 뉘임, passively restrain<\/p><p>8. 투여가능 약물: lorazepam, diazepam<\/p><p>9. 경련 후 traumatic injury 확인 후 환자 전원<\/p>","st":"<p><span style=\"color:#C00000;\">간질간질 장난치다가<\/span><\/p><p><span style=\"color:#C00000;\">역사쌤한테 따끔(TACM)하게 혼남<\/span><\/p><p><span style=\"color:#C00000;\">빈(도)정(도) 상해서 <\/span><\/p><p><span style=\"color:#C00000;\">역사쌤이랑 프리 데이트 ㅋㅎ<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">학생 정상적으로 컨트롤 안되면 역사쌤경고야<\/span><\/p><p><span style=\"color:#C00000;\">발로 까면 말 들으려나<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">그랜드마스터처럼 매니징 하려면 <\/span><\/p><p><span style=\"color:#C00000;\">sup 위치에서 입부터 쉿<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">매니징하기 깨끗한 상태에서 사이드 tongue을 restrain<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Pro처럼 약 주고<\/span><\/p><p><span style=\"color:#C00000;\">끝나고 나서 트라우마 injury 확인 후 치료 중단<\/span><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">역사썜<\/span><\/p><p><span style=\"color:#C00000;\">학생 컨트롤 안되어서<\/span><\/p><p><span style=\"color:#C00000;\">부작용 옴 – 어지럽고 의식 혼미<\/span><\/p><p><span style=\"color:#C00000;\">발로 car버리고 피 나면<\/span><\/p><p><span style=\"color:#C00000;\">Grand ma 표 대처법<\/span><\/p><p><span style=\"color:#C00000;\">치우고 옆으로 뉘우고 pass 파스<\/span><\/p><p><span style=\"color:#C00000;\">Di lo 띠로리<\/span><\/p><p><span style=\"color:#C00000;\">트라우마 랑 injury 생김<\/span><\/p>","yrs":[2025,2023],"tags":["기출"],"lab":"","pos":"T1r5"},{"id":"sd:OMED:540965a0","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>Stroke가 좌뇌에서 발생했을 때와 우뇌에서 발생했을 때 임상증상을 비교하시오. (25,22)<\/b><\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Right-side brain damage<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Left-side brain damage<\/b><\/p><\/td><\/tr><tr><td><p>1. paralyzed left side<\/p><p>2. spatial-perceptual deficit<\/p><p>3. thought impaired<\/p><p>4. quick impulsive behavior<\/p><p>5. cannot use mirror<\/p><p>6. difficulty performing tasks(잇솔질)<\/p><p>7. memory deficits<\/p><p>8. neglect of left side<\/p><\/td><td><p>1. paralyzed right side<\/p><p>2. language and speech problem<\/p><p>3. decreased auditory problem<\/p><p>4. slow, cautions, disorganized behavior<\/p><p>5. memory deficits-language based<\/p><p>6. patients anxious<\/p><\/td><\/tr><\/table>","st":"<p><span style=\"color:#C00000;\">(야구 보는 중)<\/span> <span style=\"color:#C00000;\">스트라이크!<\/span><\/p><p><span style=\"color:#C00000;\">왼쪽으로 왔는데 / 공간 인지가 안되나?<\/span><\/p><p><span style=\"color:#C00000;\">생각이 없어 / <\/span><\/p><p><span style=\"color:#C00000;\">충동적으로 / 거울 부심<\/span><\/p><p><span style=\"color:#C00000;\">Per task  퍽 탁<\/span><\/p><p><span style=\"color:#C00000;\">기억이.. 나지 않습니다<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">오른쪽.. / 말이 안 나오고 / 잘 안 들려요 / 느리니까 조심좀 / 기억 문제 때문에 / 불안해죽겠네<\/span><\/p>","yrs":[2025,2022],"tags":["기출"],"lab":"","pos":"T1r6"},{"id":"sd:OMED:b1af0af5","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>Stroke risk factor를 쓰시오. (24,21)<\/b><\/span><\/p>","a":"<p>1. hypertension<\/p><p>2. congestive heart failure<\/p><p>3. diabetes mellitus<\/p><p>4. hx. of TIAs or previous CVA<\/p><p>5. age&gt;75 yrs.<\/p><p>6. hypercholesterolemia<\/p><p>7. coronary atherosclerosis<\/p><p>8. smoking tobacco<\/p><p>- note: risk of stroke increases by a factor of 1.5 for each of these conditions.<\/p><p>- w/the combinations of several factors, the risk obviously becomes much greater<\/p>","st":"<p><span style=\"color:#C00000;\">야구의 위험)<\/span><\/p><p><span style=\"color:#C00000;\">Hype해서 <\/span><\/p><p><span style=\"color:#C00000;\">치어리더한테 heart 날리다가<\/span><\/p><p><span style=\"color:#C00000;\">Dia 잃어버린 <\/span><\/p><p><span style=\"color:#C00000;\">역사가<\/span><\/p><p><span style=\"color:#C00000;\">벌써 75년 전..<\/span><\/p><p><span style=\"color:#C00000;\">에휴 콜라나 마시자<\/span><\/p><p><span style=\"color:#C00000;\">코로 <\/span><\/p><p><span style=\"color:#C00000;\">담배냄세 에휴 담배나 펴야지<\/span><\/p>","yrs":[2024,2021],"tags":["기출"],"lab":"","pos":"T1r7"},{"id":"sd:OMED:395f5983","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>Stroke(뇌졸중)의 치과치료 시 주의사항 (25,22)<\/b><\/span><\/p>","a":"<p><b>[jb 답]<\/b><\/p><p>1. Identification of risk factors<\/p><p>a. Hypertension<\/p><p>b. Diabetes mellitus<\/p><p>c. Coronary atherosclerosis<\/p><p>d. Elevated blood cholesterol or lipid levels<\/p><p>e. Cigarette smoking<\/p><p>f. TIA (transient ischemic attack) or previous stroke<\/p><p>g. Increasing age<\/p><p>2. Encouragement to control risk factors (referral to physician if appropriate)<\/p><p>3. History of stroke<\/p><p>a. Having had a stroke places patient at high risk for having another-use caution<\/p><p>b. Urgent dental care only during first 6 months<\/p><p>c. Patient with TIAs or RINDs(reversible ischemic neurologic deficits) : no elective care<\/p><p>d. Anticoagulant drugs predispose to bleeding problems<\/p><p>- Aspirin, Clopidogrel : pretreatment bleeding time &lt; 20min<\/p><p>- Coumarin: pretreatment PT&lt;2.5sec, INR&lt;3.5<\/p><p>- Heparin: use palliative emergency dental care only<\/p><p>4. Short, stress-free, midmorning appointment scheduled<\/p><p>5. Monitoring of blood pressure and oxygen saturation<\/p><p>6. Minimum amount of anesthetic with vasoconstrictor used<\/p><p>7. No epinephrine in retraction cord<\/p><p> <\/p><p><b>[정리본 ver.]<\/b><\/p><p>1. 고혈압, 당뇨, 흡연, 관상동맥질환의 등의 risk factor 파악<\/p><p>2. risk factor 관리할 것 당부<\/p><p>3. 뇌졸중의 hx. 파악<\/p><p>- stroke 6개월 내로는 응급 치료만<\/p><p>- 항응고제 사용하는 경우 출혈에 주의<\/p><p>4. 오전 중으로 예약<\/p><p>5. 치료 중 혈압과 산소포화도 측정<\/p><p>6. 혈관수축제가 포함된 국소마취제 이용 최소화<\/p><p>7. 치은압배사에 epinephrine 사용X<\/p>","st":"<p><span style=\"color:#C00000;\">(담배 꼴초한테 하는 말)<\/span><\/p><p><span style=\"color:#C00000;\">졸라 주의 필요!<\/span><\/p><p><span style=\"color:#C00000;\">위험해!! 고당도 코피 나면 담타 증가<\/span><\/p><p><span style=\"color:#C00000;\">엥구.. 주의하라니까 6개월을 못참고<\/span><\/p><p><span style=\"color:#C00000;\">띠링띠링 안티돼버리네<\/span><\/p><p><span style=\"color:#C00000;\">아침에 또 피나서 (담배 피면)<\/span><\/p><p><span style=\"color:#C00000;\">최소 노예야<\/span><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Short ver) 치과에서 걸림<\/span><\/p><p><span style=\"color:#C00000;\">고딩이 흡연하다 걸림 risk<\/span><\/p><p><span style=\"color:#C00000;\">Risk 하지 말라고 당부함<\/span><\/p><p><span style=\"color:#C00000;\">히스토리 보니까 – 6개월 전 응급실 갔다왔고 / 피낸 적도 있던데<\/span><\/p><p><span style=\"color:#C00000;\">안되겠다 넌 오전 등교해서 <\/span><\/p><p><span style=\"color:#C00000;\">혈압 산소 체크할거야<\/span><\/p><p><span style=\"color:#C00000;\">담배피면 마취시키고<\/span><\/p><p><span style=\"color:#C00000;\">압박 드간다<\/span><\/p>","yrs":[2025,2022],"tags":["기출"],"lab":"","pos":"T1r8"},{"id":"sd:OMED:3b050093","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>Effective Communication techniques for stroke pts (23)<\/b><\/span><\/p>","a":"<p>1. Face the patient<\/p><p>2. Use slower, more deliberate, less complex pattern of speech<\/p><p>3. Communicate at eye level<\/p><p>4. Be positive<\/p><p>5. Ask yes/no questions – simple and brief<\/p><p>6. Give frequent, accurate, and immediate feedback<\/p><p>7. Use simple drawings to explain procedures<\/p><p>8. Do not underestimate or overestimate their abilities<\/p><p>9. Do not raise voice or use baby talk<\/p><p>10. Do not wear a mask when talking to the patient<\/p><p>11. Communicate also with significant other/personal care provider<\/p>","st":"<p><span style=\"color:#C00000;\">(커뮤에 올라온 사진)<\/span><\/p><p><span style=\"color:#C00000;\">얼굴을<\/span><\/p><p><span style=\"color:#C00000;\">천천히 패턴을 보니까<\/span><\/p><p><span style=\"color:#C00000;\">눈이 커뮤상이야<\/span><\/p><p><span style=\"color:#C00000;\">아냐 긍정마인드!<\/span><\/p><p><span style=\"color:#C00000;\">심플하게 피드백 해주자면<\/span><\/p><p><span style=\"color:#C00000;\">그림보다 언더야<\/span><\/p><p><span style=\"color:#C00000;\">아기피부 위해 마스크팩 케어하자<\/span><\/p>","yrs":[2023],"tags":["기출"],"lab":"","pos":"T1r9"},{"id":"sd:OMED:1788b939","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>파킨슨병의 임상증상 (24,23)<\/b><\/span><\/p>","a":"<p>1. Resting tremor (attenuated during activity)<\/p><p>2. Muscle rigidity<\/p><p>3. Slow movement (bradykinesia)<\/p><p>4. Facial impassiveness<\/p><p>- 50% 환자<\/p><p>  : musculoskeletal pain<\/p><p>  : burning, numbness, tingling<\/p><p>  : subjective feeling of restlessness<\/p><p>  : restless leg syndrome<\/p><p>  : orthostatic hypotension<\/p><p>  : bowel and bladder dysfunction<\/p><p>- 40% 환자: mood disturbance(depression, dysthymia, apathy, anxiety)<\/p><p>- 25% 환자: dementia<\/p><p>- 20% 환자: psychosis<\/p>","st":"<p><span style=\"color:#C00000;\">파김치가 되어 돌아옴..)<\/span><\/p><p><span style=\"color:#C00000;\">덜덜 떨리고 / 근육통 심함<\/span><\/p><p><span style=\"color:#C00000;\">오늘 운동은 느리게 /  패스!<\/span><\/p><p><span style=\"color:#C00000;\">뭐요 BNT (bmt 샌드위치) 먹었다고?<\/span><\/p><p><span style=\"color:#C00000;\">쉬고 싶다고? 다리를 쉬지 마<\/span><\/p><p><span style=\"color:#C00000;\">오싹하게 해줄게 당장 바벨 들어<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">무데뽀면 사이코지..<\/span><\/p>","yrs":[2024,2023],"tags":["기출"],"lab":"","pos":"T1r10"},{"id":"sd:OMED:0466f3d1","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>파킨슨병의 구내증상 (25탈)<\/b><\/span><\/p>","a":"<p>1. Excess salivation and drooling from decreased frequency of swallowing<\/p><p>2. Muscle rigidity – difficult to maintain oral hygiene<\/p><p>3. Drug used – Xerostomia, nausea, tardive dyskinesia (경직성 운동장애)<\/p>","st":"<p><span style=\"color:#C00000;\">너무 많이 운동해서 침 흘리면서 삼킬 준비 완<\/span><\/p><p><span style=\"color:#C00000;\">근육이 굳어서 입이 안 열려<\/span><\/p><p><span style=\"color:#C00000;\">약물 썼더니 침 no! ta dy 타다<\/span><\/p>","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T1r11"},{"id":"sd:OMED:736ecd97","lec":"L48f703","q":"<p><span style=\"background-color:#00FFFF;\">파킨슨병 환자 50%에서 나타나는 증상<\/span><\/p>","a":"<p>1. Musculoskeletal pain<\/p><p>2. Burning, numbness, tingling<\/p><p>3. Subjective feeling of restlessness<\/p><p>4. Restless leg syndrome<\/p><p>5. Orthostatic hypotension<\/p><p>6. Bowel and bladder dysfunction<\/p>","st":"<p><span style=\"color:#C00000;\">뭐요 BNT (bmt 샌드위치) 먹었다고?<\/span><\/p><p><span style=\"color:#C00000;\">쉬고 싶다고? 다리를 쉬지 마<\/span><\/p><p><span style=\"color:#C00000;\">오싹하게 해줄게 당장 바벨 들어<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T1r12"},{"id":"sd:OMED:0c629784","lec":"L48f703","q":"<p><span style=\"background-color:#00FFFF;\">간질환자의 구강 내 합병증<\/span><\/p>","a":"<p>1. Gingival overgrowth associated with phenytoin<\/p><p>2. Traumatic injuries such as broken teeth, tongue laceration, lip scar<\/p><p>3. Stomatitis, EM, SJS are rare adverse effects associated with phenytoin, valproic acid<\/p>","st":"<p><span style=\"color:#C00000;\">예쁘게 꾸민 팬한테)<\/span><\/p><p><span style=\"color:#C00000;\">팬한테 진짜 오바한다고 함 <\/span><\/p><p><span style=\"color:#C00000;\">트라우마 생겨서 / SEM 난겨 빼박이야<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T1r13"},{"id":"sd:OMED:698bbd95","lec":"L48f703","q":"<p><span style=\"background-color:#00FFFF;\">뇌졸중 환자의 단계별 임상증상<\/span><\/p>","a":"<p>1. Transient ischemic attack (TIA)<\/p><p>- mini stroke caused by temporarily disturbance in blood supply to a localized area of brain<\/p><p>- numbness of the face, arm, or leg in one side of body, weakness, tingling,<\/p><p>- numbness, or speech disturbance less than 10 min<\/p><p>2. Reversible ischemic neurologic deficit (RIND)<\/p><p>- neurological deficit similar to TIA that does not clear within 24 hours, but there is<\/p><p>- eventual recovery<\/p><p>3. Stroke in evolution<\/p><p>- occlusion or hemorrhage of a cerebral a.: deficit이 수 시간 지속되다가 악화됨<\/p><p>4. Completed stroke<\/p>","st":"<p><span style=\"color:#C00000;\">뇌절의 단계<\/span><\/p><p><span style=\"color:#C00000;\">1. 공격적인 미니스커트 입고 번호따기 (numb) 10분 안에<\/span><\/p><p><span style=\"color:#C00000;\">2. 리뉴얼한 식당에서 24시간만에 이벤트하기<\/span><\/p><p><span style=\"color:#C00000;\">3. 더 진화해서 오크 분장하고 세레나데 부르기<\/span><\/p><p><span style=\"color:#C00000;\">4. 고백 완성하기&gt;&lt;<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T1r14"},{"id":"sd:OMED:6bf3bdb3","lec":"L48f703","q":"<p><span style=\"background-color:#FFFF00;\"><b>근무력증 환자의 치과치료 시 주의사항 (25탈)<\/b><\/span><\/p>","a":"<p>1. Weakness of the muscles of facial expression<\/p><p>2. Dysphagia – swallowing difficulty, suction, rubber dam<\/p><p>3. Chewing difficulty<\/p><p>4. May occur dyspnea during treatment<\/p><p>5. Dental infection should be treated immediately<\/p><p>6. Avoid narcotics, barbiturates, and tranquilizers<\/p><p>7. Avoid tetracycline, streptomycin, sulfonamides, clindamycin<\/p>","st":"<p><span style=\"color:#C00000;\">(원내생 혼나는 중)<\/span><\/p><p><span style=\"color:#C00000;\">A: 근무 중에 약한 척하지 마세요 / 디스 시작: 석션도 못하고 러버댐도;;;<\/span><\/p><p><span style=\"color:#C00000;\">B: 츄~ 봐주세용<\/span><\/p><p><span style=\"color:#C00000;\">A: 치료 중에 뭐하는거죠; 즉시 나가<\/span><\/p><p><span style=\"color:#C00000;\">B: 나 바보 아니거든요! 킹받네<\/span><\/p><p><span style=\"color:#C00000;\">A: 4회 경고 시 수술 큰일납니다;;<\/span><\/p>","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T1r15"},{"id":"sd:OMED:2686bf2e","lec":"L48f703","q":"<p><span style=\"background-color:#00FF00;\">Anticonvulsant used in the management of generalized Tonic-Clonic seizures<\/span><\/p><p><span style=\"color:#7F7F7F;background-color:#00FF00;\">(과거 필기 부작용 언급)<\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>일반명<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>상품명<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>하루 성인 복용량(mg)<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>치과적 고려사항<\/b><\/p><\/td><\/tr><tr><td><p>Phenytoin<\/p><\/td><td><p>Dilantin<\/p><\/td><td><p style=\"text-align:center;\">300~400<\/p><\/td><td><p>치은비대, 감염위험성 증대, 치유지연, 치은출혈(백혈구감소증), 골다공증<\/p><\/td><\/tr><tr><td><p>Carbamazepine<\/p><\/td><td><p>Tegretol<\/p><\/td><td><p style=\"text-align:center;\">800~1600<\/p><\/td><td><p>구강건조증, 감염, 치유지연, 조화운동불능, 치은출혈(백혈구 감소증, 혈소판 감소증), 골다공증, 약물상호작용: Propoxyphene, erythromycin<\/p><\/td><\/tr><tr><td><p>Valproic acid<\/p><\/td><td><p>Depakene, Depakote<\/p><\/td><td><p style=\"text-align:center;\">1000~3000<\/p><\/td><td><p>과도한 출혈 및 정출혈, 혈소판 응집 감소, 감염 위험성 증대, 치유 지연, 치은 출혈(백혈구 감소증, 혈소판 감소증), 졸음, 약물상호작용: Aspirin, NSAIDs<\/p><\/td><\/tr><tr><td><p>Lamotrigine<\/p><\/td><td><p>Lamictal<\/p><\/td><td><p style=\"text-align:center;\">75~200<\/p><\/td><td><p>조화운동불능, 치과 치료용 의자에 앉고 내릴 때 도움이 필요할 수 있음, Stevens-Johnson 증후군의 발생 위험<\/p><\/td><\/tr><\/table>","st":"","yrs":[],"tags":["수업시간 강조"],"lab":"","pos":"T1r16"},{"id":"sd:OMED:5586636f","lec":"L48f703","q":"<p><span style=\"background-color:#00FF00;\">Drug used in the management of Parkinson's disease<\/span><\/p><p><span style=\"color:#7F7F7F;background-color:#00FF00;\">(과거 필기 부작용, 치과적 고려사항 언급)<\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>종류 및 약<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>용량(mg)<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>부작용<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>치과적 고려사항<\/b><\/p><\/td><\/tr><tr><td><p>Anticholinergic<\/p><p>Trihexyphenidyl HCl(Artane)<\/p><p>Benztropine mesylate(Cogentin)<\/p><\/td><td><p><br><\/p><\/td><td><p>진정, 요축적, 변비<\/p><\/td><td><p>구강건조증<\/p><\/td><\/tr><tr><td><p>Dopamine precursor<\/p><p>Levodopa<\/p><p>Carbidopa/Levodopa (Sinemet CR, Madopar CR)<\/p><\/td><td><p>25/100 –<\/p><p>25/250 bid<\/p><\/td><td><p>운동이상증, 피로, 두통, 불안, 혼란, 불면증, 자세성 저혈압<\/p><\/td><td><p>무도병, 운동이상증, <\/p><p>혹은 진전이 나타날 경우 치과 진료를 위해 진정요법이 필요할 수 있다; 치과치료용 의자에서 일어날 때 주의를 요함<\/p><\/td><\/tr><tr><td><p>Dopamine agonist<\/p><p>Bromocriptine mesylate(Parlodel)<\/p><\/td><td><p>5-10 tid<\/p><\/td><td><p>도파민 효과: 정신병(환각, 망상), 자세성 저혈압, 운동이상증, 구역<\/p><\/td><td><p>치과치료용 의자에서 일어날 때 주의를 요함<\/p><\/td><\/tr><tr><td><p>Pergolide mesylate (permax)<\/p><p>Pramipexole (Mirapex)<\/p><p>Ropinirole HCl (Requip)<\/p><\/td><td><p><br><\/p><\/td><td><p><br><\/p><\/td><td><p>Erythromycin과 부적절한 상호작용 일으킴<\/p><\/td><\/tr><\/table>","st":"","yrs":[],"tags":["수업시간 강조"],"lab":"","pos":"T1r17"},{"id":"sd:OMED:66b9f649","lec":"Ld212a1","q":"<p><span style=\"background-color:#FFFF00;\"><b>Diabetes 빈칸빵<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25짤, 25강조)<\/b><\/span><\/p>","a":"<p>- A disease complex with (<b>metabolic<\/b>) and (<b>vascular<\/b>) components<\/p><p>- Characterized by <b>hyperglycemia<\/b> and complications that include <b>microvascular disease<\/b> of the kidney and eye, and a variety of clinical <b>neuropathies<\/b><\/p><p>- 1형의 주요 사망 원인은 (<b>Renal failure<\/b>)<\/p><p>- 2형의 주요 사망 원인은 (<b>Myocardial infarction<\/b>)<\/p>","st":"<p><span style=\"color:#C00000;\"> 매번 / 당 올라서 / 매번 / neu 과자 깠던 기억이..<\/span><\/p>","yrs":[2025],"tags":["기출","짤","25 강조"],"lab":"","pos":"T2r2"},{"id":"sd:OMED:f7886148","lec":"Ld212a1","q":"<p><span style=\"background-color:#FFFF00;\"><b>당뇨가 질병에 이환되기 쉬운 3가지 이유 (Pathophysiology)<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>당뇨 환자에서 감염이 잘 일어나는 이유를 기술하시오.<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25, 23)<\/b><\/span><\/p>","a":"<p>1) Hyperglycemia<\/p><p>- decreased phagocytic function of granulocyte<\/p><p>- facilitate the growth of microorganism<\/p><p>2) Ketoacidosis<\/p><p>- delay the migration of granulocyte<\/p><p>- decreased phagocytic activity<\/p><p>3) Vascular wall disease<\/p><p>- microangiopathy, macroangiopathy<\/p><p>- decreased blood flow to injury area<\/p><p>- reduce oxygen tension<\/p><p>- decreased granulocyte mobilization<\/p><p><span style=\"color:#7F7F7F;\">* 당뇨는 큰 혈관뿐 아니라 micro vascular component에도 영향을 주고 neuropathy가 생김<\/span><\/p><p><span style=\"color:#7F7F7F;\">* microangiopathy : 말단에 혈액 공급 잘 안됨 → wound healing이 잘안됨 → 발가락 등의 부위에 궤양이 잘 생겨 잘라내는 일 발생<\/span><\/p>","st":"<p><span style=\"color:#C00000;\">혈당 높아 자꾸 졸려서 짜증난 상황<\/span><\/p><p><span style=\"color:#C00000;\">혈당 높아,,아씨바 (acidosis, vascular)<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Phago배고픈데 근성장 촉진한다고<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">자꾸 이동(migration)시키니까 <\/span><\/p><p><span style=\"color:#C00000;\">Phago파서 활동 안하고 싶음<\/span><\/p><p><span style=\"color:#C00000;\">Angry!! 그래놀라 막 줄 테니까 /<\/span><\/p><p><span style=\"color:#C00000;\">산소 수혈하자<\/span><\/p>","yrs":[2025,2023],"tags":["기출"],"lab":"","pos":"T2r3"},{"id":"sd:OMED:49d5e417","lec":"Ld212a1","q":"<p><span style=\"background-color:#FFFF00;\">1형 당뇨와 2형 당뇨의 임상적 특징 비교<\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p><br><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Type 1<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Type 2<\/b><\/p><\/td><\/tr><tr><td><p><b>Frequency<\/b><\/p><\/td><td><p style=\"text-align:center;\">5~10%<\/p><\/td><td><p style=\"text-align:center;\">90~95%<\/p><\/td><\/tr><tr><td><p><b>Age at onset<\/b><\/p><\/td><td><p style=\"text-align:center;\">15 yrs<\/p><\/td><td><p style=\"text-align:center;\">&gt; 40 yrs<\/p><\/td><\/tr><tr><td><p><b>Body<\/b><\/p><\/td><td><p style=\"text-align:center;\">Normal or thin<\/p><\/td><td><p style=\"text-align:center;\">Obese<\/p><\/td><\/tr><tr><td><p><b>Severity<\/b><\/p><\/td><td><p style=\"text-align:center;\">Extreme<\/p><\/td><td><p style=\"text-align:center;\">Mild<\/p><\/td><\/tr><tr><td><p><b>Insulin<\/b><\/p><\/td><td><p style=\"text-align:center;\">Almost all<\/p><\/td><td><p style=\"text-align:center;\">25~30%<\/p><\/td><\/tr><tr><td><p><b>Oral agents<\/b><\/p><\/td><td><p style=\"text-align:center;\">Few respond<\/p><\/td><td><p style=\"text-align:center;\">50% respond<\/p><\/td><\/tr><tr><td><p><b>Ketoacidosis<\/b><\/p><\/td><td><p style=\"text-align:center;\">common<\/p><\/td><td><p style=\"text-align:center;\">Uncommon<\/p><\/td><\/tr><tr><td><p><b>Complication<\/b><\/p><\/td><td><p style=\"text-align:center;\">common<\/p><\/td><td><p style=\"text-align:center;\">Less common<\/p><\/td><\/tr><tr><td><p><b>Progression<\/b><\/p><\/td><td><p style=\"text-align:center;\">rapid<\/p><\/td><td><p style=\"text-align:center;\">Slow<\/p><\/td><\/tr><tr><td><p><b>Stability<\/b><\/p><\/td><td><p style=\"text-align:center;\">unstable<\/p><\/td><td><p style=\"text-align:center;\">Stable<\/p><\/td><\/tr><tr><td><p><b>Family history<\/b><\/p><\/td><td><p style=\"text-align:center;\">common<\/p><\/td><td><p style=\"text-align:center;\">More common<\/p><\/td><\/tr><tr><td><p><b>In receptor defect<\/b><\/p><\/td><td><p style=\"text-align:center;\">Usually not found<\/p><\/td><td><p style=\"text-align:center;\">Often found<\/p><\/td><\/tr><\/table>","st":"<p>FABSIOKCPSFR<\/p><p><span style=\"color:#C00000;\">비(BI) 오(O)니까 스카(SKA)에 있던 사람들 죽는 SF 영화..CPR 필요스(S)!!<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Fab SI OK CPr SFR 쉬팔<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T2r4"},{"id":"sd:OMED:2dc9bb82","lec":"Ld212a1","q":"<p><span style=\"background-color:#00FFFF;\">당뇨 Pathophysiology &amp; Complications<\/span><\/p>","a":"<p>1. Hyperglycemia<\/p><p>- unable to take glucose into the cells, cellular starvation<\/p><p>- increased production of glucose<\/p><p>- glucose excretion in the urine<\/p><p>2. Protein metabolism<\/p><p>- proteolysis<\/p><p>3. Fat metabolism<\/p><p>- ketone body, metabolic acidosis<\/p>","st":"<p><span style=\"color:#C00000;\">당 단백질 지방)<\/span><\/p><p><span style=\"color:#C00000;\">Star 굶어서 그런지<\/span><\/p><p><span style=\"color:#C00000;\">Glucose 포도당 없는<\/span><\/p><p><span style=\"color:#C00000;\">Pro 가 먹는 케토(keto)식단도 좋음<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T2r5"},{"id":"sd:OMED:90139256","lec":"Ld212a1","q":"<p><span style=\"background-color:#FFFF00;\"><b>현재 당뇨의 진단 기준을 설명하시오 (ADA criteria) (24,22,21,20~)<\/b><\/span><\/p><p><br><\/p><p><span style=\"background-color:#FFFF00;\"><b>25년도:<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>Prediabetes 빈칸을 채우시오.<\/b><\/span><\/p><p>FPG: ( ) – ( ) mg/dl<\/p><p>PP2: ( ) – ( ) mg/dl<\/p><p>A1C: ( ) – ( ) %<\/p>","a":"<p><b>[ADA Criteria for the Diagnosis of DM-Current]<\/b><\/p><p>1) FBS(FPG) ≥ 126mg/dL or                                          <span style=\"color:#7F7F7F;\">* FBS (fasting blood sugar = FPG, fasting plasma glucose)<\/span><\/p><p>2) Symptoms and signs of diabetes plus casual plasma glucose ≥ 200mg/dL or<\/p><p>3) PP2 ≥ 200mg/dL or                   <span style=\"color:#7F7F7F;\">* PP2: 식사 후 2시간 뒤 혈당 높아져 insulin이 작용해 insulin이 전체 혈당을 낮춰준 시점<\/span><\/p><p>4) HbA₁C ≥ 6.5%                                                          <span style=\"color:#7F7F7F;\">* 당화헤모글로빈 (glycosylated Hb)<\/span><\/p><p><br><\/p><p>① Normal<\/p><p>- FBS: &lt;100mg/dL and<\/p><p>- PP2 : 140mg/dL<\/p><p>② <b>Impaired glucose metabolism (<\/b><span style=\"background-color:#FFFF00;\"><b>pre-diabetes<\/b><\/span><b>)<\/b><\/p><p>- FBS: <b>100 – 126<\/b> mg/dl (impaired fasting glucose)<\/p><p>- PP2: <b>140 – 199<\/b> mg/dl (impaired glucose tolerance)<\/p><p>- A1C: <b>5.7 – 6.4 <\/b>%<\/p><p>③ DM<\/p><p>- FBS: ≥126mg/dL or<\/p><p>- PP2: ≥200mg/dL<\/p><p>- HBA1C: ≥6.5<b> <\/b>%<\/p>","st":"<p><span style=\"color:#C00000;\">굶었는데도(FBS) 이리(12) 육중(6)하다니<\/span><\/p><p><span style=\"color:#C00000;\">그럼(glu) PT(PP2)를 200번 받아보자<\/span><\/p><p><span style=\"color:#C00000;\">한번(Hb) 66사이즈를 55 사이즈(6.5)로 만들어보는거야<\/span><\/p>","yrs":[2025,2024,2022,2021,2020],"tags":["기출"],"lab":"","pos":"T2r6","rv":[{"k":"year","m":"연도 범위 표기 (24,22,21,20~)"}]},{"id":"sd:OMED:e856f36d","lec":"Ld212a1","q":"<p><span style=\"background-color:#00FFFF;\">Glycohemoglobin (HbA1C) 수치<\/span><\/p>","a":"<table><tr><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>HbA1C<\/b><\/p><\/td><td colspan=\"2\" style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Comparison to Average Blood Sugar Level<\/b><\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">6%<\/p><\/td><td colspan=\"2\"><p style=\"text-align:center;\">Reflects 120 mg/dL<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">7%<\/p><\/td><td colspan=\"2\"><p style=\"text-align:center;\">Reflects 150 mg/dL<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">8%<\/p><\/td><td colspan=\"2\"><p style=\"text-align:center;\">Reflects 180 mg/dL<\/p><\/td><\/tr><tr><td><p style=\"text-align:center;\">9%<\/p><\/td><td colspan=\"2\"><p style=\"text-align:center;\">Reflects 210 mg/dL<\/p><\/td><\/tr><tr><td colspan=\"2\" style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Glycohemoglobin (%)<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Interpretation<\/b><\/p><\/td><\/tr><tr><td colspan=\"2\"><p style=\"text-align:center;\">4-6 (6.5)<\/p><\/td><td><p>Normal range<\/p><\/td><\/tr><tr><td colspan=\"2\"><p style=\"text-align:center;\">&lt; 6.5 – 7.0 (7.5)<\/p><\/td><td><p>Good control of Diabetes, Therapeutic Target<\/p><\/td><\/tr><tr><td colspan=\"2\"><p style=\"text-align:center;\">7.6 – 8.9<\/p><\/td><td><p>Fair control of Diabetes<\/p><\/td><\/tr><tr><td colspan=\"2\"><p style=\"text-align:center;\">9 - 20<\/p><\/td><td><p>Poor control of Diabetes<\/p><\/td><\/tr><\/table>","st":"","yrs":[],"tags":["과거기출"],"lab":"","pos":"T2r7"},{"id":"sd:OMED:dcd3803a","lec":"Ld212a1","q":"<p><span style=\"background-color:#FFFF00;\"><b>Oral hypoglycemic agents 당뇨병 치료약물 기전<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25매칭, 과거객관식)<\/b><\/span><\/p><p><br><\/p><p><b>25년도:<\/b><\/p><p><b>기전 5가지 주고 약물 종류 5가지랑 매칭 (p.7 참고)<\/b><\/p>","a":"<p>1) Sulfonylurea, Meglitinides, Incretin(GLP-1) analogue<\/p><p>→ Enhance insulin secretion<\/p><p>2) DPP-4 (Dipeptidyl peptidase-4) inhibitors<\/p><p>→ Enhance insulin secretion<\/p><p>→ Inhibit enzymatic breakdown of GLP-1<\/p><p>3) Biguanides(Metformin)<\/p><p>→ Reduce hepatic glucose production<\/p><p>→ Improve peripheral glucose utilization<\/p><p>4) Alpha-glucosidase inhibitor<\/p><p>→ Delay carbohydrate digestion<\/p><p>5) Thiazolidinediones<\/p><p>→ Enhance insulin sensitivity<\/p><p>6) SGLT2 Inhibitor<\/p><p>→ Resorption↓ Excretion↑ of <u>glucose<\/u><\/p><p> <\/p><p><span style=\"background-color:#FFFF00;\"><b>*Oral hypoglycemic agent 중 기전이 다른 하나는?<\/b><\/span><\/p><p>1) Sulfonylureas<\/p><p>2) Meglitinides<\/p><p>3) incretin analogues<\/p><p>4) dipeptidyl peptidase-4 inhibitors<\/p><p>5) biguanides                                                                       (답 : 5)<\/p><p> <\/p><p><b>*Oral hypoglycemic Agents 기전<\/b><\/p><p>1) Increase insulin secretion<\/p><p>2) Reduce glucose production<\/p><p>3) Increase insulin sensitivity<\/p><p>4) Enhance glucagon-like peptide 1 (GLP-1) action<\/p><p>5) Promote urinary excretion of glucose<\/p><p>6) Monotherapy, Combination therapy<\/p>","st":"<p><span style=\"color:#C00000;\">(1) Insulin secretion<\/span><\/p><p><span style=\"color:#C00000;\">: sulfonylurea, meglitinides, incretin(GLP-1) analogue, DPP-4(dipeptidyl peptidase-4) inhibitor<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">(2) reduce glucose production<\/span><\/p><p><span style=\"color:#C00000;\">: biguanide, metformin<\/span><\/p><p><span style=\"color:#C00000;\">비굴(bigu)한 생산(production)직이 나(me)야<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">(3) delay carbohydrate digestion<\/span><\/p><p><span style=\"color:#C00000;\">: alpha-glucosidase inhibitor<\/span><\/p><p><span style=\"color:#C00000;\">효소이므로 digestion에 관여<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">(4) enhance insulin sensitivity<\/span><\/p><p><span style=\"color:#C00000;\">: thiazolidinediones<\/span><\/p><p><span style=\"color:#C00000;\">뛰(thi)어노는 애들 감각 예민<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">(5) Resorption↓ Excretion↑ of glucose<\/span><\/p><p><span style=\"color:#C00000;\">: SGLT2 inhibitor<\/span><\/p><p><span style=\"color:#C00000;\">transporter니까 재흡수 분비에 관여<\/span><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">insulin insulin<\/span><\/p><p><span style=\"color:#C00000;\">glucose glucose glucagon <\/span><\/p><p><span style=\"color:#C00000;\">combination<\/span><\/p>","yrs":[2025],"tags":["기출","매칭","과거기출"],"lab":"","pos":"T2r8"},{"id":"sd:OMED:bff50085","lec":"Ld212a1","q":"<p><span style=\"background-color:#FFFF00;\"><b>당뇨병의 구강 내 합병증<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25, 23)<\/b><\/span><\/p>","a":"<p>1) Accelerated periodontal disease<\/p><p>2) Periodontal abscesses<\/p><p>3) Dry mouth<\/p><p>4) Increased incidence and severity of caries<\/p><p>5) Poor wound healing<\/p><p>6) Infection<\/p><p>7) Oral ulceration<\/p><p>8) Candidiasis<\/p><p>9) Numbness, burning, or pain in oral tissue<\/p>","st":"<p><span style=\"color:#C00000;\">당 떨어진 상태에서 합병증)<\/span><\/p><p><span style=\"color:#C00000;\">엑셀(accel) 밟고<\/span><\/p><p><span style=\"color:#C00000;\">Dry 드라이브 하다가<\/span><\/p><p><span style=\"color:#C00000;\">Ab 본 사이에<\/span><\/p><p><span style=\"color:#C00000;\">Car 쾅<\/span><\/p><p><span style=\"color:#C00000;\">상처 힐링도 안되고 / 감염 심각한데 <\/span><\/p><p><span style=\"color:#C00000;\">Ul can 어떤 얼간이야<\/span><\/p><p><span style=\"color:#C00000;\">Numb 번호 따감<\/span><\/p>","yrs":[2025,2023],"tags":["기출"],"lab":"","pos":"T2r9"},{"id":"sd:OMED:8019ca3f","lec":"Ld212a1","q":"<p><span style=\"background-color:#00FFFF;\">치주질환-DM : vicious cycle<\/span><\/p>","a":"<p>- 치주질환은 전신 염증과 인슐린 저항성 악화 : generation of inflammatory cytokines<\/p><p>- 치주질환 치료 후 당뇨 환자 metabolic control 향상<\/p><p>- 0.4% reduction of HbA1c at 3 months<\/p>","st":"","yrs":[],"tags":["과거기출"],"lab":"","pos":"T2r10"},{"id":"sd:OMED:95978b60","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\"><b>Sexually Transmitted Infections (STI) 원인 분류<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>성전파성 감염을 야기하는 세균, 바이러스 매개 질병들을 각 원인별로 나누어 해당하는 질환을 나열하시오<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25,22,20,19,18)<\/b><\/span><\/p><p><span style=\"color:#7F7F7F;background-color:#FFFF00;\"><b>(한글로도 알아둘 것)<\/b><\/span><\/p>","a":"<p><b>[Bacteria]<\/b><\/p><p>1. gonorrhea (임질)<\/p><p>2. chlamydia (클라미디아)<\/p><p>3. syphilis (매독)<\/p><p><b>[Viruses]<\/b><\/p><p>1. human papillomavirus (인간 유두종 바이러스)<\/p><p>2. genital herpes (성기포진)<\/p><p><b>[Parasites]<\/b><\/p><p>1. trichomoniasis (트리코모나스증)<\/p>","st":"<p><span style=\"color:#C00000;\">성병환자오면<\/span><\/p><p><span style=\"color:#C00000;\">GCS랑 go ch syphi<\/span><\/p><p><span style=\"color:#C00000;\">PG 피지<\/span><\/p><p><span style=\"color:#C00000;\">Tri Cho 세번 체크해 <\/span><\/p>","yrs":[2025,2022,2020,2019,2018],"tags":["기출"],"lab":"","pos":"T3r2"},{"id":"sd:OMED:7261b1cb","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\">구순, 상순에 종창을 일으킬 수 있는 원인균? (22,20)<\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>악안면 상순에 종기 형성, 해면정맥 혈전증 유발하는 균?(24,22,21,20)<\/b><\/span><\/p>","a":"<p><b>Staphylococcus infection(포도상구균 감염)  - <\/b>(답은 이것만 쓰면 됨)<\/p><p>1. Staphylococcus aureus           2. Staphylococcus epidermidis            3. Staphylococcus saprophyticus<\/p><p><br><\/p><p><span style=\"color:#7F7F7F;\">* 안면부, 상순에 생긴 종기 → 상순정맥 → 해면정맥동 혈전증, 뇌막염, 뇌염<\/span><\/p><p><span style=\"color:#7F7F7F;\">* 감염의 90% 이상이 penicillinase 형성 세균 → penicillin에 저항 세균<\/span><\/p>","st":"<p><span style=\"color:#C00000;\">상순이<\/span><\/p><p><span style=\"color:#C00000;\">앞이(epi) 안보이는 아우라 가짐<\/span><\/p><p><span style=\"color:#C00000;\">쌉(sap) 소리 하지 마라<\/span><\/p>","yrs":[2024,2022,2021,2020],"tags":["기출"],"lab":"","pos":"T3r3"},{"id":"sd:OMED:48aea80c","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\"><b>매독의 단계별 구강 임상적 특징<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25탈)<\/b><\/span><\/p>","a":"<p>1기 : chancre (경성하감) *통증 없는 단단한(경결감 있는) 궤양<\/p><p>2기 : mucous patch(점막반), 피부 발진<\/p><p>3기 : gumma (고무종), 피하육아종<\/p><p>-1,2 기는 대개 동통이 없고 전염성이 강하다        -3 기는 무통성, 2차감염 가능, 전염성 없음<\/p>","st":"<p><span style=\"color:#C00000;\">독해지는 단계)<\/span><\/p><p><span style=\"color:#C00000;\">나한테도 기회(chance)가 왔다<\/span><\/p><p><span style=\"color:#C00000;\">Muc pat 먹뱉 컨셉으로 급발진해서<\/span><\/p><p><span style=\"color:#C00000;\">Gumma 고무 먹음 피하하ㅏ<\/span><\/p>","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T3r4"},{"id":"sd:OMED:27952b4e","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\"><b>고위험, 저위험 HPV(Human papilloma virus infection, 인간 유두종 바이러스 감염) 및 유발 질병 서술하는 문제<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25,24,22,21)<\/b><\/span><\/p>","a":"<p>1. 발암성, 고위험 HPV 감염 (예: HPV type16,18)<\/p><p> → 자궁 경부, 음경, 외음부, 질, 항문 및 구강 인두 암 및 전암병소 유발<\/p><p>2. 비발암성, 저위험 HPV 감염 (예: HPV type 6,11)<\/p><p> → 성병사마귀(venereal wart), 첨형사마귀(condyloma wart) 유발<\/p>","st":"<p><span style=\"color:#C00000;\">위험한 첨단 성<\/span><\/p><p><span style=\"color:#C00000;\">첨단 성에 갖힌 11세기 비운의 공주<\/span><\/p><p><span style=\"color:#C00000;\">항상 자외선도 못보고 ㅅㅂ(18) 욕만하다<\/span><\/p><p><span style=\"color:#C00000;\">죽음(암)..<\/span><\/p>","yrs":[2025,2024,2022,2021],"tags":["기출"],"lab":"","pos":"T3r5"},{"id":"sd:OMED:613c3193","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\"><b>Acute HIV infection의 임상증상을 나열하시오 (23)<\/b><\/span><\/p><p><br><\/p><p><span style=\"background-color:#FFFF00;\">AIDS의 임상증상<\/span><\/p>","a":"<p>1) swollen lymph glands<\/p><p>2) unusual lesions on the tongue; skin rashes and bumps<\/p><p>3) nausea, vomiting, and diarrhoea<\/p><p>4) cough and shortness of breath<\/p><p>5) chronic fatigue<\/p><p>6) fever, chills, and night sweats<\/p><p>7) rapid weight loss<\/p><p>8) blurred or distorted vision<\/p>","st":"<p><span style=\"color:#C00000;\">*우동먹고 급성으로 응급실감<\/span><\/p><p><span style=\"color:#C00000;\">Swollen배부른데<\/span><\/p><p><span style=\"color:#C00000;\">untong우동먹었더니<\/span><\/p><p><span style=\"color:#C00000;\">skinrash알러지+nausea vomiting<\/span><\/p><p><span style=\"color:#C00000;\">기침, 숨도 잘 안 쉬어짐<\/span><\/p><p><span style=\"color:#C00000;\">fatigue피곤하고<\/span><\/p><p><span style=\"color:#C00000;\">fever열 나네<\/span><\/p><p><span style=\"color:#C00000;\">rapid빨리<\/span><\/p><p><span style=\"color:#C00000;\">응급차 blur불러<\/span><\/p>","yrs":[2023],"tags":["기출"],"lab":"","pos":"T3r6"},{"id":"sd:OMED:e184fdcd","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\"><b>Acute HIV infection 시 구강 내 소견을 쓰시오 (25탈)<\/b><\/span><\/p>","a":"<p>1) Sores<\/p><p>2) Thrush<\/p>","st":"","yrs":[2025],"tags":["기출","탈"],"lab":"","pos":"T3r7","note":"위 임상증상이랑 구분할 것!!"},{"id":"sd:OMED:226b4ba4","lec":"L95cf01","q":"<p><b>Kaposi’s sarcoma 임상적 특징<\/b><\/p><p><b>(26탈대비)<\/b><\/p>","a":"<p>1. 초기병변: 편평하고 청색, 청적색 병변과 감별<\/p><p>2. 진행병변: 짙은 적색에 경결성증식, 궤양 형성, 만졌을 때 딱딱한 느낌<\/p><p>3. 구강 내-구개, 치은에 호발 / 그외-피부에 호발<\/p>","st":"","yrs":[],"tags":["26 탈 대비"],"lab":"","pos":"T3r8"},{"id":"sd:OMED:44c28862","lec":"L95cf01","q":"<p><span style=\"background-color:#00FFFF;\">HIV/AIDS는 같은 의미인가?<\/span><\/p>","a":"<p>아니다. HIV를 지닌 환자에서 면역결핍이 나타나면 AIDS라 한다<\/p>","st":"","yrs":[],"tags":["과거기출"],"lab":"","pos":"T3r9"},{"id":"sd:OMED:a68facce","lec":"L95cf01","q":"<p><span style=\"background-color:#00FFFF;\">성기에 수포를 일으키는 원인<\/span><\/p>","a":"<p><b>HSV-1,2 (대부분은 HSV-2)<\/b><\/p><p><span style=\"color:#7F7F7F;\">*HHV-1 : herpes simplex virus type 1, 주로 입술포진, 구강포진<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-2 : herpes simplex virus type 2, 주로 생식기포진<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-3 : Varicella zoster virus (VZV)<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-4 : Epstein-Barr Virus (EBV)<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-5 : Cytomegalovirus (CMV)<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-6 : Human herpesvirus 6<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-7 : human herpesvirus 7<\/span><\/p><p><span style=\"color:#7F7F7F;\">*HHV-8 : Kaposi’s sarcoma-associated herpesvirus (KSHV)<\/span><\/p>","st":"","yrs":[],"tags":["과거기출"],"lab":"","pos":"T3r10"},{"id":"sd:OMED:502923cb","lec":"L95cf01","q":"<p><span style=\"background-color:#FFFF00;\"><b>Oral hairy leukoplakia, Burkitt lymphoma <\/b><\/span><span style=\"background-color:#FFFF00;\">일으키는 바이러스 이름<\/span>?<\/p>","a":"<p><b>Epstein-Barr virus (EBV)<\/b><\/p>","st":"","yrs":[],"tags":["기출"],"lab":"","pos":"T3r11"},{"id":"sd:OMED:216ba7dd","lec":"L95cf01","q":"<p><span style=\"background-color:#00FFFF;\">EBV에 의해 발생하는 질병 나열 (3)<\/span><\/p>","a":"<p>1) oral hairy leukoplakia<\/p><p>2) Burkitt lymphoma<\/p><p>3) infectious mononucleosis<\/p>","st":"<p><span style=\"color:#C00000;\">EDM 페스티벌에서<\/span><\/p><p><span style=\"color:#C00000;\">머리(hair) 가리려고 버킷(burkit)모자 쓰다가 너 뭐니(mo)? 소리 들음<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T3r12"},{"id":"sd:OMED:a2f1ee4e","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\">면역억제하는 약물과 부작용<\/span><\/p>","a":"<p><b>[Immunosuppressive agent]<\/b><\/p><p>1. Cyclosporine<\/p><p>2. Azathioprine<\/p><p>3. Prednisone<\/p><p><br><\/p><p><b>[Complication]<\/b><\/p><p>1. Azathioprine: bone marrow suppression (leukopenia, anemia, thrombocytopenia)<\/p><p>→ infection, bleeding<\/p><p>2. Cyclosporine<\/p><p>: no bone marrow suppression but severe kidney and liver changes possible<\/p><p>→ bleeding, hypertension, tumor, gingival hyperplasia<\/p>","st":"<p><span style=\"color:#C00000;\">면역 억제 CAP쳐~<\/span><\/p><p><span style=\"color:#C00000;\">싸이클 아자아자 프리하게<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T4r2"},{"id":"sd:OMED:38ba3e4d","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\"><b>과도한 면역억제 시 발생할 수 있는 합병증<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>Signs of Overimmunosuppression in posttransplant pts.<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25,23)<\/b><\/span><\/p>","a":"<p>1. Viral infection (HSV, HBV, HIV 등)<\/p><p>2. Bacterial infections (respiratory, wound)<\/p><p>3. Fungal infection (candidiasis, pulmonary)<\/p><p>4. Delayed healing<\/p><p>5. Excessive bleeding<\/p><p>6. Hypertension<\/p><p>7. Cushingoid reaction (edema, ascites)<\/p><p>8, Addison’s reaction (adverse reaction to stress)<\/p><p>9. DM<\/p><p>10. Anemia<\/p><p>11. Osteoporosis<\/p><p>12. Tumor<\/p>","st":"<p><span style=\"color:#C00000;\">오버하지마)<\/span><\/p><p><span style=\"color:#C00000;\">봐봐<\/span><\/p><p><span style=\"color:#C00000;\">뻥이야ㅋ<\/span><\/p><p><span style=\"color:#C00000;\">데카(DEHCA)에서 DM 옴<\/span><\/p><p><span style=\"color:#C00000;\">너 아웃(AOT)이래<\/span><\/p>","yrs":[2025,2023],"tags":["기출"],"lab":"","pos":"T4r3"},{"id":"sd:OMED:475edd57","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\"><b>장기이식 환자에게 예방적 항생제의 처방을 특히 적극적으로 고려해야하는 상황을 쓰시오. (25탈)<\/b><\/span><\/p><p><span style=\"color:#7F7F7F;\">(위의 답 4개만 쓰면 됨)<\/span><\/p><p><br><\/p><p><span style=\"background-color:#FFFF00;\"><b>이식예정인 환자에 대한 예방적 항생제 사용 표준지침<\/b><\/span><b> (23)<\/b><\/p><p><span style=\"color:#7F7F7F;\">(JB에 표 내용 포함 X)<\/span><\/p>","a":"<p>1. Risk of endocarditis<\/p><p>2. Decreased WBC count<\/p><p>3. Infection in operative fluid<\/p><p>4. BMT patients: more aggressive regimen than other transplant patients<\/p><p><br><\/p><p><b>[예방적 항생제 표준지침 – jb답]<\/b><\/p><p>- Amoxicillin 2g PO 1h before에 Metronidazole 500mg PO 1h before 추가 투여<\/p><p>- Amoxicillin-penicillin에 allergy있는 경우: Vancomycin or Imipenem 1g IV 1h before<\/p><p>- 경구투여 불가능한 경우 Ampicillin 2g IV 1h before에 Metronidazole 500mg IV 1h before 추가투여<\/p><p>(아래 표는 참고)<\/p><table><tr><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Medication<\/b><\/p><\/td><td style=\"background-color:#F2F2F2\"><p style=\"text-align:center;\"><b>Regimen<\/b><\/p><\/td><\/tr><tr><td><p>Amoxicillin plus metronidazole 500mg orally 1hr before procedure<\/p><\/td><td><p>2g orally 1hr before procedure<\/p><\/td><\/tr><tr><td><p>If amoxicillin – penicillin allergy<\/p><p>: Vancomycin or Imipenem<\/p><\/td><td><p>1g IV infused slowly over 1hr preoperatively<\/p><\/td><\/tr><tr><td><p>Unable to take oral medication<\/p><p>Ampicillin plus metronidazole 500mg IV 1hr before procedure<\/p><\/td><td><p>2g IV 1hr before procedure<\/p><\/td><\/tr><\/table>","st":"<p><span style=\"color:#C00000;\">장기 원내생 – 적극적으로 뛰어야함)<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">항...엔도랑 오퍼 언제 채우냐<\/span><\/p><p><span style=\"color:#C00000;\">Count 채우기 위해 <\/span><\/p><p><span style=\"color:#C00000;\">BM 병맛 aggressive 환자들도 들어간다<\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">A men <\/span><\/p><p><span style=\"color:#C00000;\">V Ip 환자 와서<\/span><\/p><p><span style=\"color:#C00000;\">A men<\/span><\/p>","yrs":[2025,2023],"tags":["기출","탈"],"lab":"","pos":"T4r4"},{"id":"sd:OMED:fad1eb02","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\">장기이식 환자에서의 Oral complications<\/span><\/p>","a":"<p>1. Rejection<\/p><p>2. Overimmunosuppression: mucositis, herpes, SCC, CMV<\/p><p>3. Side effects of immunosuppressive agents<\/p><p>: infection, delayed healing, bleeding, tumor<\/p><p>4. GVHD: ulcer, salivary gl. dysfunction, palatal mucocele<\/p>","st":"<p><span style=\"color:#C00000;\">장기자랑 부작용)<\/span><\/p><p><span style=\"color:#C00000;\">로제(ROSE)랑 인디밴드팀(IDBT)<\/span><\/p><p><span style=\"color:#C00000;\">하고 싶다...<\/span><\/p><p><span style=\"color:#C00000;\">진부하다(GVHD)...<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T4r5"},{"id":"sd:OMED:6690baaf","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\">Radiation/chemotherapy가 예정된 암 환자의 치과치료 시기와 순서<\/span><\/p><p><span style=\"background-color:#FFFF00;\">Head and Neck Irradiation 예정인 환자의 치과치료 순서, 시기<\/span><\/p>","a":"<p>1. At least 2 weeks before radiation: Extraction<\/p><p>2. 1 week before<\/p><p>   : treat symptomatic nonvital teeth.<\/p><p>   : Asymptomatic teeth even with periapical involvement can be delayed.<\/p><p>3. Infection, perio, extraction first / caries, endo, restoration later<\/p><p>4. Prophylaxis, RPD removed<\/p>","st":"<p><span style=\"color:#C00000;\">(헤어질 준비 중) 얼 유 레디?<\/span><\/p><p><span style=\"color:#C00000;\">2주 동안 Ex랑 싸우고<\/span><\/p><p><span style=\"color:#C00000;\">1주 전에 심통 나서 아쉽...<\/span><\/p><p><span style=\"color:#C00000;\">IPE 이빠이  cer 새 남자 만나기위해<\/span><\/p><p><span style=\"color:#C00000;\">자기 PR이나 해야지<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T4r6"},{"id":"sd:OMED:417078ad","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\">Allergic reaction의 Sign &amp; Symptom 7가지<\/span><\/p>","a":"<p>1. Urticaria<\/p><p>2. Swelling<\/p><p>3. Skin rash<\/p><p>4. Chest tightness<\/p><p>5. Dyspnea, shortness of breath<\/p><p>6. Rhinorrhea<\/p><p>7. Conjunctivitis<\/p>","st":"<p><span style=\"color:#C00000;\">US SC DR ConJun<\/span><\/p><p><span style=\"color:#C00000;\">(알러지가 왜 났게)<\/span><\/p><p><span style=\"color:#C00000;\">미국(US) 스케일링(SC) 드럽(DR)<\/span><\/p><p><span style=\"color:#C00000;\">아무래도 꽁짜(ConJun)라...<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T4r7"},{"id":"sd:OMED:9673aa4e","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\"><b>알러지 환자 Dental management – Emergency<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>(25,23)<\/b><\/span><\/p>","a":"<p>1. Head down or supine position<\/p><p>2. Maintain airway patency<\/p><p>3. Administer oxygen<\/p><p>4. Call 119. Check pulse<\/p><p>5. 0.3~0.5ml 1:1000 epinephrine (thigh better)<\/p><p>6. Intravenous diphenhydramine: 50~100mg<\/p>","st":"<p><span style=\"color:#C00000;\">응급 알러지 발생)<\/span><\/p><p><span style=\"color:#C00000;\">HP 떨어지는 중<\/span><\/p><p><span style=\"color:#C00000;\">필요한 건 산소 / 119 / pulse<\/span><\/p><p><span style=\"color:#C00000;\">이디(easy)하죠? (ED)<\/span><\/p>","yrs":[2025,2023],"tags":["기출"],"lab":"","pos":"T4r8"},{"id":"sd:OMED:e784b702","lec":"L99f76c","q":"<p><span style=\"background-color:#00FF00;\">이식환자 Dental management - treatment planning: pretransplant<\/span><\/p><p><span style=\"background-color:#00FF00;\"><b>이 부분은 암기하라고 25년 언급!<\/b><\/span><\/p><p><br><\/p><p>- Patients maintaining their dentition<\/p>","a":"<p>1. Extract all nonrestorable teeth.<\/p><p>2. Extract all teeth with severe periodontal disease (clinical attachment loss of 5mm or greater).<\/p><p>3. Perform endodontic treatment or extraction of nonvital teeth.<\/p><p>4. Perform denture adjustments(if needed).<\/p><p>5. Perform dental prophylaxis.<\/p><p>6. Provide elective dental treatment as time and necessity permit.<\/p><p>7. Initiate an active, effective, oral hygiene program:<\/p><p>a. Tooth brushing, flossing<\/p><p>b. Diet modification if indicated<\/p><p>c. Topical fluorides<\/p><p>d. Plaque control, calculus removal<\/p><p>e. Chlorhexidine or Listerine mouthwash (daily)<\/p>","st":"<p><span style=\"color:#C00000;\">Mc몽 치아 이식)<\/span><\/p><p><span style=\"color:#C00000;\">나라 잃고<\/span><\/p><p><span style=\"color:#C00000;\">PD 잃고 <\/span><\/p><p><span style=\"color:#C00000;\">엔도 발치 <\/span><\/p><p><span style=\"color:#C00000;\">치과 치료 한건데 <\/span><\/p><p><span style=\"color:#C00000;\">치과 예방한건데<\/span><\/p><p><span style=\"color:#C00000;\">시간과 필요성을 인정받지 못해서<\/span><\/p><p><span style=\"color:#C00000;\">AO아오 프로그램에서 쫓겨남<\/span><\/p><p><span style=\"color:#C00000;\">- 바다 가서 Fuck PC방이나 가자<\/span><\/p>","yrs":[],"tags":["수업시간 강조"],"lab":"","pos":"T4r9"},{"id":"sd:OMED:54f4e026","lec":"L99f76c","q":"<p><span style=\"background-color:#00FF00;\"><b>이식환자 dental management – medical considerations: pretransplant<\/b><\/span><\/p>","a":"<p>1. Consider severe medical complications from the particular organ system<\/p><p>2. Thorough dental evaluation: infection site<\/p><p>3. Consult with patient’s physician<\/p><p>4. Avoid any dental treatment for <b>6 months<\/b> after transplantation<\/p><p>5. Oral hygiene instructions<\/p>","st":"<p><span style=\"color:#C00000;\">이식 후 6개월 동안 치과치료 X<\/span><\/p><p><span style=\"color:#C00000;\">따라서 이식 전에 필요한 치과치료를 모두 해야 함<\/span><\/p>","yrs":[],"tags":["수업시간 강조"],"lab":"","pos":"T4r10"},{"id":"sd:OMED:11574b5c","lec":"L99f76c","q":"<p><span style=\"background-color:#00FF00;\"><b>암환자 dental management – medical considerations 관련 치과의사의 역할<\/b><\/span><\/p>","a":"<p>1. Early recognition of disease: history taking and physical exam<\/p><p>2. Biopsy of lesion that does not heal in <b>2 weeks<\/b> of treatment<\/p>","st":"","yrs":[],"tags":["수업시간 강조"],"lab":"","pos":"T4r11"},{"id":"sd:OMED:3518e434","lec":"L99f76c","q":"<p><span style=\"background-color:#FFFF00;\"><b>방사선, 화학항암요법 치료 에정인 환자 발치 시 주의사항과 치료계획 (25탈)<\/b><\/span><\/p><p><br><\/p><p><span style=\"background-color:#00FF00;\"><b>Guidelines for tooth extraction in patients schedule to receive head and neck irradiation (including the mouth) or chemotherapy<\/b><\/span><\/p>","a":"<p><b>[Recommendations before radiation or chemo] – 이건 26jb답임<\/b><\/p><p>- Management of salivary flow: Salagen<\/p><p>- Extraction: poor or hopeless teeth, acute infection, severe periodontal teeth, bony edges smoothed.<\/p><p>- Primary closure<\/p><p>- Chronic inflammatory lesions: treat or eradicate.<\/p><p>- Minimize oral discomfort during therapy<\/p><p><b>[Time schedule] – 내 기준 치료계획 답(주미)<\/b><\/p><p>- At least 2 wk before radiation: extraction<\/p><p>- 1 wk before: treat symptomatic nonvital teeth asymptomatic teeth even w/ periapical involvement can be delayed<\/p><p>- Infection, perio, extraction first, caries, endo, restoration latter.<\/p><p>- Prophylaxis, RPD removed.<\/p><p><br><\/p><p><b>JB 긴 버전 답)   [Indicators of extraction]<\/b><\/p><p>1. <b>Pocket depths 6mm or greater<\/b>, excessive mobility, purulence on probing<\/p><p>2. Presence of periapical inflammation<\/p><p>3. Broken-down, nonrestorable, nonfunctional, or partially erupted tooth in a patient who is noncompliant with oral hygiene measures<\/p><p>4. <b>Patient lack of interest in saving tooth/teeth<\/b><\/p><p>5. Inflammatory (e.g., pericoronitis)&lt; infectious, or malignant osseous disease associated with questionable tooth<\/p><p><br><\/p><p><b>[Extraction guidelines] 수치 알고 있어야 한다고 25년 언급<\/b><\/p><p>1. Extraction should be performed with minimal trauma, with timing as follows:<\/p><p>- At least 2 weeks, ideally 3 weeks, before initiation of radiation therapy<\/p><p>- At least 5 days (in maxilla) before initiation of chemotherapy<\/p><p>- At least 7 days (in mandible) before initiation of chemotherapy<\/p><p>2. Trim bone at wound margins to eliminate sharp edges<\/p><p>3. Obtain primary closure<\/p><p>4. Avoid intraalveolar hemostatic packing agents which can serve as a nidus for microbial growth.<\/p><p>5. Transfuse if the platelet count is less than 50,000/mm3<\/p><p>6. Delay extraction if the white blood count is less than 2000/μm or expected to be this level within 10 days; alternatively, prophylactic antibiotics (cephalosporin) can be used with extractions that are mandatory.<\/p>","st":"<p><span style=\"color:#EE0000;\">암걸린 남자친구랑 헤어지기)<\/span><\/p><p><span style=\"color:#EE0000;\">매니징 하다 몸살남<\/span><\/p><p><span style=\"color:#EE0000;\">희망이 없다 ex로 헤어짐<\/span><\/p><p><span style=\"color:#EE0000;\">문 닫고  closure<\/span><\/p><p><span style=\"color:#EE0000;\">만성 미련도 없애버려<\/span><\/p><p><span style=\"color:#EE0000;\">이 불편함 최소화해 <\/span><\/p><p><br><\/p><p><span style=\"color:#C00000;\">2주 동안 Ex랑 싸우고<\/span><\/p><p><span style=\"color:#C00000;\">1주 전에 심통 나서 아쉽...<\/span><\/p><p><span style=\"color:#C00000;\">IPE 이빠이  cer 새 남자 만나기위해<\/span><\/p><p><span style=\"color:#C00000;\">자기 PR이나 해야지<\/span><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">Indicators 요인들)<\/span><\/p><p><span style=\"color:#C00000;\">PD가 <\/span><\/p><p><span style=\"color:#C00000;\">인플레 infla 예상하면서<\/span><\/p><p><span style=\"color:#C00000;\">Complain만 하거나<\/span><\/p><p><span style=\"color:#C00000;\">무관심한 사람들에게 <\/span><\/p><p><span style=\"color:#C00000;\">뼈있는 Mal함. 질문을 던지라고<\/span><\/p>","yrs":[2025],"tags":["수업시간 강조","기출","탈"],"lab":"","pos":"T4r12"},{"id":"sd:OMED:1db1c189","lec":"L99f76c","q":"<p><span style=\"background-color:#00FF00;\">cancer therapy 중 dental management<\/span> <\/p><p><br><\/p><p>(과거에 수치 기억하라고 언급)<\/p>","a":"<p>1. Maintenance care for cancer therapy complications.<\/p><p>2. Provided between chemo cycles: <b>17~20 days after session<\/b><\/p><p>3. Routine dental care delayed until cancer therapy is complete.<\/p>","st":"","yrs":[],"tags":["수업시간 강조"],"lab":"","pos":"T4r13"},{"id":"sd:OMED:28d325d2","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\"><b>우울증의 진단기준 (25,23)<\/b><\/span><\/p>","a":"<p>≥ 5 symptoms including depressed mood and/or anhedonia<\/p><p>Symptoms present for ≥ 2 weeks<\/p><p>other symptoms may include<\/p><p>1) significant weight change<\/p><p>2) psychomotor agitation/retardation *정신 초조,과잉/지연,둔화<\/p><p>3) pervasive loss of energy/fatigue<\/p><p>4) feelings of worthlessness/excessive or inappropriate guilt<\/p><p>5) difficulty concentrating<\/p><p>6) sleep disturbance<\/p><p>7) recurrent thoughts of death/suicide<\/p>","st":"<p><span style=\"color:#C00000;\">연예인 우울증)<\/span><\/p><p><span style=\"color:#C00000;\">Depressed 우울해서 나 anhe!! <\/span><\/p><p><span style=\"color:#C00000;\">다른(other) 사람들은<\/span><\/p><p><span style=\"color:#C00000;\">체중(weight) 빼는데 (자긴 못빼서)<\/span><\/p><p><span style=\"color:#C00000;\">초조(psychomotor agitation)하고<\/span><\/p><p><span style=\"color:#C00000;\">피곤(fatigue)하게 걱정하다<\/span><\/p><p><span style=\"color:#C00000;\">쓸모(worthlessness)없는 생각으로<\/span><\/p><p><span style=\"color:#C00000;\">집중(concentration) 못하고<\/span><\/p><p><span style=\"color:#C00000;\">잠도 못 자다가(sleep disturbance)<\/span><\/p><p><span style=\"color:#C00000;\">자살(suicide)함<\/span><\/p>","yrs":[2025,2023],"tags":["기출"],"lab":"","pos":"T5r2"},{"id":"sd:OMED:f974707f","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\"><b>우울증 치료에 사용되는 약의 구강 내 부작용과 처치 방법<\/b><\/span><\/p><p><span style=\"background-color:#FFFF00;\"><b>TCA의 구강내 부작용과 처치방법<\/b><\/span><\/p><p><br><\/p><p><span style=\"background-color:#FFFF00;\"><b>SSRI 구강 내 합병증 쓰고 해결방법 쓰시오. (25,24)<\/b><\/span><\/p><p><br><\/p><p>(답: Xerostomia, Dysgeusia, Stomatitis, Glossitis, Bruxism<\/p><p>주치의와 상담해서 약제변경을 고려한다.)<\/p>","a":"<p><b>[구강 내 부작용]<\/b><\/p><p>1) TCA: Xerostomia(Dry mouth), potentiation of pressor effect<\/p><p>→ Saliva substitute의 사용 혹은 TCA 약제 대신 SSRI 사용<\/p><p>2) Lithium: Xerostomia, Lichenoid stomatitis, metallic taste<\/p><p>3) SSRI: Xerostomia, Dysgeusia, Stomatitis, Glossitis, Bruxism<\/p><p><br><\/p><p><b>[처치방법]<\/b><\/p><p>1) 약물 대신 electroconvulsive therapy *전기충격요법<\/p><p>2) 구강건조증 증상 완화를 위해 인공타액 투여<\/p><p>3) 이갈이가 심할 경우 치아 보호를 위해 mouth guard 제작<\/p>","st":"<p><span style=\"color:#C00000;\">우울증 처치방법~)<\/span><\/p><p><span style=\"color:#C00000;\">TV(TCA) 많이 보면 기분 좋아짐 (potentiation)<\/span><\/p><p><span style=\"color:#C00000;\">리모컨(Li)으로 매일(me) 보는<\/span><\/p><p><span style=\"color:#C00000;\">쇼(S) 틀어봐 (홈쇼핑)<\/span><\/p><p><span style=\"color:#C00000;\">디게 싸게 나온 SBG 소불고기<\/span><\/p>","yrs":[2025,2024],"tags":["기출"],"lab":"","pos":"T5r3"},{"id":"sd:OMED:71c138e7","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\"><b>Tumor과 관련되어서 가장 적합한 위장관 약은? (25)<\/b><\/span><\/p>","a":"<p><b>Octreotide<\/b><\/p><p>(답 불확실 - jb 출처 못 찾겠다고 나와있음)<\/p>","st":"","yrs":[2025],"tags":["기출"],"lab":"","pos":"T5r4"},{"id":"sd:OMED:77610eb4","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\"><b>Schizoprenia drug에 의한 tardive dyskinesia 발생기전 및 특징을 쓰시오 (24,23)<\/b><\/span><\/p><p><br><\/p><p><br><\/p><p><span style=\"background-color:#FFFF00;\">조현병 환자에서 Dyskinesia 발생하는 원리 및 특징, 치료방법<\/span><\/p>","a":"<p><span style=\"color:#7F7F7F;\">*oral dyskinesia : 구강운동 이상증<\/span><\/p><p><span style=\"color:#7F7F7F;\">*tardive dyskinesia : 지연성 운동 이상증, 항정신병 약물 장기 복용 후 수개월 ~ 수년뒤 발생하는 지속적이고 불수의적인 이상운동<\/span><\/p><p><b>[병리기전]<\/b><\/p><p>Conventional antipsychotics (dopamine antagonists) 약물치료 시,<\/p><p>Blocking of dopamine D2 receptors of mesolimbic system 발생<\/p><p>→ Oral dyskinesia와 Tardive dyskinesia 나타남<\/p><p><b>[특징]<\/b><\/p><p>1) high prevalence of bruxism and signs of TMD<\/p><p>2) Actual pain sensitivity thresholds are higher<\/p><p>- TMD 문제를 겪기 쉽지만, 높은 고통 역치로 인해 진단과 치료가 늦음<\/p><p>- Serious clinical consequences<\/p><p><b>[치료방법]<\/b><\/p><p>conventional antipsychotics (DA antagonist)를 부작용이 덜한 atypical antipsychotics (serotonin-dopamine antagonist)로 바꿔준다<\/p><p><br><\/p><p><b>(참고) <\/b><b><u>oral<\/u><\/b><u> <\/u><b><u>dyskinesia<\/u><\/b> complication (8)<\/p><p>- Tooth wear<\/p><p>- Oral pain/injury<\/p><p>- TMD<\/p><p>- Speech impairment<\/p><p>- Chewing difficulties<\/p><p>- Inadequate food intake (weight loss)<\/p><p>- Retention loss of RPD<\/p><p>- Social sequelae  <span style=\"color:#7F7F7F;\">(social sequelae : 사회적 후유증)<\/span><\/p>","st":"<p><span style=\"color:#C00000;\">D2 receptor antagonist → serotonin dopamine-antagonist<\/span><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">TMD 고통스러워! Serious해<\/span><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><br><\/p><p><span style=\"color:#C00000;\">구강(oral)내과에서 TMD 차팅하는데<\/span><\/p><p><span style=\"color:#C00000;\">고통으로<\/span><\/p><p><span style=\"color:#C00000;\">말도 못하고<\/span><\/p><p><span style=\"color:#C00000;\">씹지도 못하는<\/span><\/p><p><span style=\"color:#C00000;\">살이 쪽 빠진 환자가 왔다.<\/span><\/p><p><span style=\"color:#C00000;\">보철 RPD로 리퍼 보냈더니 <\/span><\/p><p><span style=\"color:#C00000;\">사회 난리남<\/span><\/p>","yrs":[2024,2023],"tags":["기출"],"lab":"","pos":"T5r5"},{"id":"sd:OMED:8a5be833","lec":"L1626ef","q":"<p><span style=\"background-color:#00FFFF;\">조현병 환자에게 anti-cholinergic medication 시 발생하는 합병증<\/span><\/p>","a":"<p><span style=\"color:#7F7F7F;\">*조현병으로 antipsychotic 복용 → movement disorder 유발 -&gt; movement disorder 해결 위해 anticholinergic 복용 → 부작용<\/span><\/p><p>1) EKG 변화<\/p><p>2) 기립성 저혈압<\/p><p>3) 변비<\/p><p>4) blurred vision<\/p><p>5) 코막힘<\/p><p>6) 구강건조증<\/p>","st":"<p><span style=\"color:#C00000;\">조온나 변비…)<\/span><\/p><p><span style=\"color:#C00000;\">변비 치료제를<\/span><\/p><p><span style=\"color:#C00000;\">코스트코에서 샀다<\/span><\/p><p><span style=\"color:#C00000;\">구식이라 그런지 막혀버림<\/span><\/p><p><span style=\"color:#C00000;\">어케(EK)?? <\/span><\/p><p><span style=\"color:#C00000;\">Blurr 모자이크 좀,, <\/span><\/p><p><span style=\"color:#C00000;\">기절함..<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T5r6"},{"id":"sd:OMED:49173b6c","lec":"L1626ef","q":"<p><span style=\"background-color:#00FFFF;\">조현병 증상 (3)<\/span><\/p>","a":"<p>1) positive<\/p><p>- 없어야 할 증상이 있는 것<\/p><p>-exaggeration, distortion of normal function<\/p><p>-delusion, hallucination (auditory, visual, tactile) *망상과 환각<\/p><p>2) disorganized<\/p><p>- rapid shift of ideas, incoherent speech, poor thought relation, bizarre behavior<\/p><p>3) negative<\/p><p>- 있어야 할 증상이 없는 것 *감정적 반응 적음<\/p><p>- flat emotion, lack of motivation, monotony of speech, social withdrawal<\/p>","st":"<p><span style=\"color:#C00000;\">아침(조식)먹는데 할머니 만난 썰<\/span><\/p><p><span style=\"color:#C00000;\">과장(exaggeration)이 아니고<\/span><\/p><p><span style=\"color:#C00000;\">디(de)따 큰 할(hal)머니가<\/span><\/p><p><span style=\"color:#C00000;\">빠르게(rapid) 걸어오더니<\/span><\/p><p><span style=\"color:#C00000;\">나한테 말거심(speech)<\/span><\/p><p><span style=\"color:#C00000;\">생각도 못함 (thought)<\/span><\/p><p><span style=\"color:#C00000;\">너무놀라 감정관리(emotion) 못하고<\/span><\/p><p><span style=\"color:#C00000;\">화들짝 움직여(motivation) 도망감(withdrawal)<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T5r7"},{"id":"sd:OMED:e62cd1e7","lec":"L1626ef","q":"<p><span style=\"background-color:#00FFFF;\">Neuroleptic drug (신경이완제) 복용환자에서 Epi 사용시 주의사항 (3)<\/span><\/p>","a":"<p>1) Epi : 1:100,000 2 capsule 이 최대<\/p><p>2) retraction cord 사용 가능<\/p><p>3) slow injection<\/p>","st":"<p><span style=\"color:#C00000;\">신경이완제 복용으로<\/span><\/p><p><span style=\"color:#C00000;\">다시(re) 인싸(in) 달성<\/span><\/p><p><span style=\"color:#C00000;\">개이(2)득<\/span><\/p>","yrs":[],"tags":["과거기출"],"lab":"","pos":"T5r8"},{"id":"sd:OMED:c42020b7","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\"><b>Bulimia nervosa의 구강악안면 영역에서 볼 수 있는 증상 (24,22)<\/b><\/span><\/p>","a":"<p><span style=\"color:#7F7F7F;\">*bulimia nervosa(폭식증), anorexia nervosa(거식증)<\/span><\/p><p>1) Lingual erosion<\/p><p>2) Tooth sensitivity<\/p><p>3) Xerostomia<\/p><p>4) Dental caries<\/p><p>5) Perio ds (periodontal disease)<\/p><p>6) Enlarged parotid<\/p><p>7) Poor oral hygiene<\/p>","st":"<p><span style=\"color:#C00000;\">폭식증 환자 입안을 들여다보니<\/span><\/p><p><span style=\"color:#C00000;\">우식/치주질환 많음<\/span><\/p><p><span style=\"color:#C00000;\">제로(xero) 음료 많이 먹고<\/span><\/p><p><span style=\"color:#C00000;\">칫솔 열심히 안하고 (poor oral hygiene)<\/span><\/p><p><span style=\"color:#C00000;\">많이(enlarged) 먹기만 하니<\/span><\/p><p><span style=\"color:#C00000;\">치아(tooth) 부식됨<\/span><\/p>","yrs":[2024,2022],"tags":["기출"],"lab":"","pos":"T5r9"},{"id":"sd:OMED:f58a80bc","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\">Bulimia nervosa 의 임상소견 (4)<\/span><\/p>","a":"<p>1) chronic sore/inflamed throat<\/p><p>2) unexplained damage to teeth<\/p><p>3) swollen cheeks – due to damage to the parotid glands<\/p><p>4) broken blood vessels may be seen in the eyes<\/p>","st":"<p><span style=\"color:#C00000;\">폭식증 환자 중에<\/span><\/p><p><span style=\"color:#C00000;\">먹방 인플루(infla)언서 많음<\/span><\/p><p><span style=\"color:#C00000;\">설명할 수 없이(unexplainable) 양볼 한 가득(swollen cheek) 많이 먹는 먹방 인플루언서<\/span><\/p><p><span style=\"color:#C00000;\">혈관 다 망함(broken BV)<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T5r10"},{"id":"sd:OMED:6789d5f3","lec":"L1626ef","q":"<p><span style=\"background-color:#FFFF00;\"><b>Anorexia nervosa의 구강악안면 영역에서 볼 수 있는 증상<\/b><\/span><\/p>","a":"<p>1) Xerostomia<\/p><p>2) Enlarged parotid<\/p><p>3) Mucosal atrophy<\/p>","st":"<p><span style=\"color:#C00000;\">Anorexia(거식증) 환자는<\/span><\/p><p><span style=\"color:#C00000;\">많이(enlarged) 먹(mu)어도<\/span><\/p><p><span style=\"color:#C00000;\">살이 제로(xero)<\/span><\/p>","yrs":[],"tags":["기출"],"lab":"","pos":"T5r11"}]};
